export const categories = [
  ["Advanced Java", "Advanced Java"]
] as const;

// ---- Topics ----
export const topics = [
  // ==================== JAVA EE / JAKARTA EE BASICS (20) ====================
  ["Advanced Java", "What is Java EE (Jakarta EE) and what are its main components?", "java-ee-overview", "Define Java EE and list its key components.", "**Direct answer :**\nJava EE (now Jakarta EE) is a set of specifications that extend the Java SE platform with enterprise features. Its main components include Servlets, JSP, EJB, JPA, JMS, JTA, JAX-RS, JAX-WS, CDI, and Security. It provides a standard for building large-scale, multi-tiered, scalable, and secure enterprise applications.\n\n**Why this is asked :**\nInterviewers ask this to check whether you understand the enterprise Java ecosystem and can differentiate between SE and EE. They want to see if you know the key specifications and their purposes, and how they fit into modern enterprise development.\n\n**Breaking it down :**\nJava EE (now Jakarta EE) is a set of specifications that extend the Java SE platform with enterprise features. Its main components include Servlets (web request handling), JSP (view technology), EJB (business logic), JPA (persistence), JMS (messaging), JTA (transactions), JAX-RS (RESTful services), JAX-WS (SOAP services), CDI (dependency injection), and Security. These specifications are implemented by application servers like WildFly, TomEE, and GlassFish.\n\nThe key point is to understand that Java EE provides a standardized, component-based architecture for enterprise applications, promoting portability and separation of concerns. In modern development, many of these have been superseded by Spring, but they remain foundational.\n\n**How to structure your spoken answer :**\nStart with a one-sentence definition of Java EE. Then list the main components, grouping them by layer (web, business, persistence, messaging, etc.). Mention that Jakarta EE is the new name and that application servers provide implementations. Finish by noting that while Spring is popular, knowledge of Java EE is still valuable for legacy systems and for understanding the standards.\n\n**Follow-up angle to anticipate :**\nBe ready to explain the difference between Java EE and Spring, or to dive deeper into a specific component like JPA or EJB. Also expect questions about the migration from Java EE to Jakarta EE."],
  ["Advanced Java", "What is a Servlet and what is its lifecycle?", "servlet-lifecycle", "Explain Servlet and its lifecycle.", "**Direct answer :**\nA Servlet is a Java class that handles HTTP requests and responses in a web container. Its lifecycle consists of: loading and instantiation, initialization (\`init()\`), service (\`service()\`), and destruction (\`destroy()\`). The container manages these phases.\n\n**Why this is asked :**\nInterviewers ask this to verify your understanding of the foundational web technology in Java EE. They want to see if you know how servlets work under the hood and how they are managed by the container, which is crucial for debugging and performance tuning.\n\n**Breaking it down :**\nA Servlet is a Java class that handles HTTP requests and responses in a web container. Its lifecycle consists of:\n- Loading and instantiation: The container loads the servlet class and creates an instance (usually once).\n- Initialization: The container calls \`init()\` method to initialize the servlet (e.g., reading configuration). This happens once.\n- Service: For each request, the container calls \`service()\` method, which dispatches to \`doGet()\`, \`doPost()\`, etc. based on HTTP method.\n- Destruction: The container calls \`destroy()\` before removing the servlet (e.g., on application shutdown), allowing cleanup.\n\nThe container manages these phases, and the servlet is a singleton per definition (unless configured otherwise).\n\n**How to structure your spoken answer :**\nStart with a definition of a Servlet. Then explain the lifecycle step by step, mentioning what happens at each phase and when. Emphasize that \`init()\` and \`destroy()\` are called once, while \`service()\` is called for every request. Finish with a practical example (e.g., a simple servlet that prints a greeting).\n\n**Follow-up angle to anticipate :**\nBe ready to discuss thread safety in servlets (since they are singletons), the difference between \`GenericServlet\` and \`HttpServlet\`, and how to handle asynchronous requests."],
  ["Advanced Java", "What is the difference between `GenericServlet` and `HttpServlet`?", "generic-vs-http-servlet", "Compare GenericServlet and HttpServlet.", "**Direct answer :**\n\`GenericServlet\` is protocol-independent and provides a basic servlet interface. \`HttpServlet\` extends \`GenericServlet\` and adds HTTP-specific methods like \`doGet()\`, \`doPost()\`, etc. In practice, we use \`HttpServlet\` for web applications.\n\n**Why this is asked :**\nInterviewers ask this to check if you understand the inheritance hierarchy and the specialization of servlets. It also tests your knowledge of when to use which.\n\n**Breaking it down :**\n\`GenericServlet\` is an abstract class that implements the \`Servlet\` interface. It provides a protocol-independent implementation, with \`service()\` method being abstract. \`HttpServlet\` extends \`GenericServlet\` and adds HTTP-specific functionality, including \`doGet()\`, \`doPost()\`, \`doPut()\`, etc. It also implements the \`service()\` method to route to the appropriate HTTP method handler.\n\nMost web applications use \`HttpServlet\` because they need HTTP capabilities. \`GenericServlet\` is rarely used directly.\n\n**How to structure your spoken answer :**\nStart by stating that both are abstract classes for servlets. Explain that \`GenericServlet\` is protocol-agnostic, while \`HttpServlet\` specializes for HTTP. Mention that you typically extend \`HttpServlet\` and override \`doGet\`/\`doPost\`. Give an example.\n\n**Follow-up angle to anticipate :**\nBe ready to discuss other servlet-related classes like \`HttpServletRequest\`, \`HttpServletResponse\`, and how to handle sessions."],
  ["Advanced Java", "What is a `Filter` and how does it differ from a `Servlet`?", "filter-vs-servlet", "Explain Filter and its differences.", "**Direct answer :**\nA \`Filter\` intercepts requests before they reach a servlet (or after a servlet responds) to perform pre-processing and post-processing tasks. Unlike servlets, filters do not generate responses themselves; they are used for tasks like authentication, logging, compression, etc.\n\n**Why this is asked :**\nInterviewers ask this to test your understanding of the request processing pipeline and how to implement cross-cutting concerns in Java web applications.\n\n**Breaking it down :**\nFilters are components that can be applied to a set of URLs (via mapping) and can modify request/response headers, perform authentication, logging, or transformation. They are chained and executed in order. A filter has \`init()\`, \`doFilter()\`, and \`destroy()\` methods. \`doFilter()\` receives \`FilterChain\` to pass the request to the next filter or servlet.\n\nServlets are the endpoint that generate responses, while filters are intermediaries. Filters can be used for common tasks without polluting servlet code.\n\n**How to structure your spoken answer :**\nDefine a filter and its purpose. Explain the lifecycle methods. Compare with servlets: filters don't generate responses, they modify requests/responses and can be chained. Provide examples: logging, authentication, compression. Mention the filter chain.\n\n**Follow-up angle to anticipate :**\nBe ready to explain how to create and configure a filter in \`web.xml\` or via annotations, and discuss ordering."],
  ["Advanced Java", "What is a `Listener` in Java EE?", "listener-javaee", "Explain Listeners.", "**Direct answer :**\nA \`Listener\` is a Java class that responds to events in the web container, such as application startup/shutdown, session creation/destruction, or request handling. They are used to perform tasks like initializing resources or cleaning up.\n\n**Why this is asked :**\nInterviewers ask this to see if you know how to hook into the container lifecycle and manage resources globally.\n\n**Breaking it down :**\nListeners implement specific interfaces like \`ServletContextListener\`, \`HttpSessionListener\`, \`ServletRequestListener\`. They are notified when events occur. For example, \`ServletContextListener\` has \`contextInitialized()\` and \`contextDestroyed()\` methods, called when the web application starts and stops. They are configured in \`web.xml\` or via \`@WebListener\` annotation.\n\n**How to structure your spoken answer :**\nDefine a listener as an event handler for container events. List common types: context, session, request. Explain with an example: using \`ServletContextListener\` to load a database connection pool at startup. Mention that they are useful for resource management and initialization.\n\n**Follow-up angle to anticipate :**\nBe ready to discuss the lifecycle of a web application and how listeners fit in, and the difference between listeners and filters."],
  ["Advanced Java", "What is JSP and how does it work?", "jsp-overview", "Explain JSP.", "**Direct answer :**\nJSP (JavaServer Pages) is a view technology that allows embedding Java code in HTML pages. It is compiled into a servlet by the container at runtime. JSPs are used for presentation logic, separating it from business logic.\n\n**Why this is asked :**\nInterviewers ask this to check your knowledge of server-side rendering and how Java web applications were traditionally built.\n\n**Breaking it down :**\nJSP pages contain HTML, CSS, JavaScript, and special JSP tags (like scriptlets, expressions, directives, and custom tags). When a JSP is requested, the container translates it into a Java servlet class, compiles it, and executes it. The generated servlet handles the request and produces the HTML output.\n\nJSPs can use JSTL (JSP Standard Tag Library) and Expression Language (EL) to minimize Java code in the view.\n\n**How to structure your spoken answer :**\nDefine JSP as a server-side view technology. Explain the translation process: JSP -> servlet -> response. Mention that JSPs are often used with MVC where JSP is the view. Note that modern frameworks like JSF or Thymeleaf are alternatives, but JSP is still used in legacy systems.\n\n**Follow-up angle to anticipate :**\nBe ready to discuss JSP life cycle, implicit objects, JSTL, and the differences between JSP and servlets."],
  ["Advanced Java", "What are the JSP implicit objects?", "jsp-implicit-objects", "List JSP implicit objects.", "**Direct answer :**\nJSP implicit objects are predefined variables that are available in JSP pages without declaration. They include: \`request\`, \`response\`, \`out\`, \`session\`, \`application\`, \`config\`, \`pageContext\`, \`page\`, and \`exception\`.\n\n**Why this is asked :**\nInterviewers ask this to test if you know the built-in objects that make JSP easier to use.\n\n**Breaking it down :**\n- \`request\`: \`HttpServletRequest\`\n- \`response\`: \`HttpServletResponse\`\n- \`out\`: \`JspWriter\` for output\n- \`session\`: \`HttpSession\`\n- \`application\`: \`ServletContext\`\n- \`config\`: \`ServletConfig\`\n- \`pageContext\`: \`PageContext\` provides access to page attributes and other objects\n- \`page\`: reference to the current servlet instance (rarely used)\n- \`exception\`: available only in error pages, holds the thrown exception.\n\n**How to structure your spoken answer :**\nList the objects briefly, explaining the purpose of each. Emphasize the most commonly used ones: request, response, out, session, application. Give an example: using \`session.setAttribute()\` to store user data.\n\n**Follow-up angle to anticipate :**\nBe ready to explain the scopes (page, request, session, application) and how to access attributes."],
  ["Advanced Java", "What is the difference between JSP and Servlets?", "jsp-vs-servlets", "Compare JSP and Servlets.", "**Direct answer :**\nServlets are Java classes that handle requests and generate responses programmatically. JSPs are text-based documents that embed Java code in HTML, making them easier for presentation. Servlets are better for business logic and control, JSPs for view rendering.\n\n**Why this is asked :**\nInterviewers ask this to see if you understand the separation of concerns and when to use each.\n\n**Breaking it down :**\n- **Servlets**: Pure Java, better for complex logic, manipulation of request/response, and handling non-HTML content (e.g., JSON, XML). They are compiled classes.\n- **JSP**: HTML with embedded code, easier for generating dynamic HTML, supports tags (JSTL) to reduce Java code. They are translated into servlets at runtime.\n\nBoth are used together in MVC: Servlet as controller, JSP as view.\n\n**How to structure your spoken answer :**\nDefine each. Explain that servlets are code-centric, JSPs are template-centric. Mention the MVC pattern. State that JSPs are easier for designers, but servlets are more powerful for complex logic. In modern practice, JSP is less popular with the rise of frontend frameworks and REST APIs.\n\n**Follow-up angle to anticipate :**\nBe ready to discuss the evolution of view technologies and when you'd choose JSP vs Thymeleaf or React."],
  ["Advanced Java", "What is JSTL and why is it used?", "jstl", "Explain JSTL.", "**Direct answer :**\nJSTL (JSP Standard Tag Library) is a set of custom tags for JSP that provide common functionality like iteration, conditionals, formatting, and database access, reducing the need for scriptlets.\n\n**Why this is asked :**\nInterviewers ask this to check if you know how to write clean JSPs without scriptlets, promoting good practices.\n\n**Breaking it down :**\nJSTL includes tag libraries for core (c:forEach, c:if), formatting (fmt:formatDate), SQL (sql:query), and XML (x:...). It uses EL (Expression Language) for accessing attributes. Using JSTL improves readability and maintainability.\n\n**How to structure your spoken answer :**\nDefine JSTL as a standard tag library. Explain its benefits: eliminates scriptlets, promotes separation of concerns, provides common tasks. Give an example: using \`<c:forEach>\` to iterate over a list. Mention that JSTL is often used with EL.\n\n**Follow-up angle to anticipate :**\nBe ready to discuss the core tags and how to configure JSTL in a project."],
  ["Advanced Java", "What is EL (Expression Language) in JSP?", "el-jsp", "Explain EL.", "**Direct answer :**\nEL (Expression Language) is a simple language for accessing data in JSPs, using syntax like \`${expression}\`. It can access attributes, JavaBeans properties, maps, and call methods. It was introduced to simplify JSPs and replace scriptlets.\n\n**Why this is asked :**\nInterviewers ask this to check your knowledge of how to fetch data in JSP pages.\n\n**Breaking it down :**\nEL can access objects from page, request, session, and application scopes. It supports operators (arithmetic, relational, logical), and can call methods on objects. It is often used with JSTL. EL also supports implicit objects like \`param\`, \`header\`, \`cookie\`, \`initParam\`, etc.\n\n**How to structure your spoken answer :**\nDefine EL and show the syntax. Explain how to access attributes: \`${user.name}\` or \`${user['name']}\`. Mention scopes and implicit objects. Give an example: displaying request parameters with \`${param.name}\`.\n\n**Follow-up angle to anticipate :**\nBe ready to discuss the difference between EL and JSP scriptlets, and the benefits of EL."],
  ["Advanced Java", "What is a `Session` and how is it managed in Java web applications?", "session-management", "Explain session management.", "**Direct answer :**\nA \`Session\` is a user-specific context that persists across multiple requests. In Java web apps, sessions are managed via \`HttpSession\` object, created by the container. Sessions can be tracked using cookies (JSESSIONID) or URL rewriting. They can store attributes and have a timeout.\n\n**Why this is asked :**\nInterviewers ask this to test your understanding of state management in stateless HTTP.\n\n**Breaking it down :**\n\`HttpSession\` is obtained via \`request.getSession()\`. It allows storing attributes (\`setAttribute\`, \`getAttribute\`). Sessions can be invalidated manually or time out (configured in web.xml). Session tracking uses cookies; if cookies are disabled, URL rewriting is used by appending \`jsessionid\` to URLs. For security, session IDs should be regenerated after login to prevent fixation attacks.\n\n**How to structure your spoken answer :**\nDefine a session and why it's needed. Explain how to get and use \`HttpSession\`. Mention cookie vs URL rewriting. Discuss session timeout and invalidation. Touch on security aspects (session fixation).\n\n**Follow-up angle to anticipate :**\nBe ready to discuss session clustering in distributed environments, and alternatives like JWT for stateless authentication."],
  ["Advanced Java", "What is the difference between `Session` and `Cookie`?", "session-vs-cookie", "Compare Session and Cookie.", "**Direct answer :**\nA \`Session\` stores data on the server side, while a \`Cookie\` stores data on the client side. Sessions are more secure and can store larger data, but they increase server memory. Cookies are limited in size (4KB) and can be tampered with, but they persist across browser sessions.\n\n**Why this is asked :**\nInterviewers ask this to check if you understand the differences and when to use each for state management.\n\n**Breaking it down :**\n- **Session**: Server-side storage, accessible via \`HttpSession\`. Data persists across requests for a user. Can store objects. Secure because data never leaves server. But sessions have memory overhead and need clustering in distributed setups.\n- **Cookie**: Client-side storage, sent with every HTTP request. Limited size (about 4KB). Can be set with expiration. Easily accessible to client (can be stolen if not secure). Used for tracking (JSESSIONID) or storing user preferences.\n\n**How to structure your spoken answer :**\nDefine both. Compare based on storage location, size, security, lifetime, and use cases. Give examples: session for user identity, cookie for language preference. Emphasize that session ID is often stored in a cookie.\n\n**Follow-up angle to anticipate :**\nBe ready to discuss secure cookie attributes (HttpOnly, Secure, SameSite) and session invalidation."],
  ["Advanced Java", "What is a `ServletContext` and how is it different from `ServletConfig`?", "servletcontext-vs-servletconfig", "Compare ServletContext and ServletConfig.", "**Direct answer :**\n\`ServletConfig\` provides configuration for a single servlet (init parameters). \`ServletContext\` provides access to application-wide data and resources, shared across all servlets. \`ServletContext\` is accessible via \`getServletContext()\`, while \`ServletConfig\` is passed to \`init()\`.\n\n**Why this is asked :**\nInterviewers ask this to check your understanding of scopes and configuration in Java web applications.\n\n**Breaking it down :**\n- \`ServletConfig\`: Per-servlet configuration, defined in \`web.xml\` with \`<init-param>\`. Obtained in \`init()\` method. Used for servlet-specific settings.\n- \`ServletContext\`: Application-level, accessible to all servlets. Used for global parameters, shared resources (e.g., database connection pool), and logging.\n\n**How to structure your spoken answer :**\nDefine both. Explain their scopes: config is per servlet, context is per application. Show how to access each. Provide examples: servlet config for a specific file path, context for a database driver.\n\n**Follow-up angle to anticipate :**\nBe ready to discuss how to set context and init parameters in \`web.xml\` and via annotations."],
  ["Advanced Java", "What are `application` scopes in JSP? Explain page, request, session, application.", "jsp-scopes", "Explain JSP scopes.", "**Direct answer :**\nScopes define the accessibility of attributes in JSP/Servlets. \`page\` is limited to the current JSP page, \`request\` to the current request, \`session\` to the user session, and \`application\` to the entire web application. Each scope has a corresponding object: \`pageContext\`, \`request\`, \`session\`, \`application\`.\n\n**Why this is asked :**\nInterviewers ask this to test your knowledge of data sharing and lifecycle in web apps.\n\n**Breaking it down :**\n- **Page**: Only valid within the current JSP page. Use \`pageContext.setAttribute()\`. Rarely used.\n- **Request**: Valid for the current HTTP request, can be forwarded to other resources. Use \`request.setAttribute()\`.\n- **Session**: Valid for the user's session across multiple requests. Use \`session.setAttribute()\`.\n- **Application**: Valid for the entire application, shared by all users. Use \`application.setAttribute()\`. Must be thread-safe.\n\n**How to structure your spoken answer :**\nList the four scopes, their lifetimes, and associated objects. Explain typical usage: request for passing data between servlet and JSP, session for user login, application for global counters or caches.\n\n**Follow-up angle to anticipate :**\nBe ready to discuss memory implications and best practices for using scopes."],
  ["Advanced Java", "How do you handle file uploads in a Java web application?", "file-upload-java", "Explain file upload handling.", "**Direct answer :**\nFile uploads are handled using \`multipart/form-data\` encoding. In Servlet 3.0+, you can use \`@MultipartConfig\` and \`request.getPart()\` to access uploaded files. For older versions, libraries like Apache Commons FileUpload are used.\n\n**Why this is asked :**\nInterviewers ask this to check if you know how to handle a common real-world requirement.\n\n**Breaking it down :**\n- With Servlet 3.0+: Annotate the servlet with \`@MultipartConfig\`, then use \`request.getPart(\"fieldName\")\` to get \`Part\` object, and use \`part.getInputStream()\` or \`part.write()\` to save.\n- With Apache Commons FileUpload: Create a \`DiskFileItemFactory\`, \`ServletFileUpload\`, parse the request, and iterate over \`FileItem\`.\n\n**How to structure your spoken answer :**\nStart by mentioning the need for \`multipart/form-data\`. Explain the Servlet 3.0 approach and the older approach. Give a simple code snippet for Servlet 3.0. Mention configuration for file size limits.\n\n**Follow-up angle to anticipate :**\nBe ready to discuss handling large files, progress tracking, and validation."],
  ["Advanced Java", "What is a `WebSocket` and how does it relate to Java EE?", "websocket-javaee", "Explain WebSocket in Java EE.", "**Direct answer :**\nWebSocket is a protocol for full-duplex communication over a single TCP connection. In Java EE, the \`@ServerEndpoint\` annotation and the \`javax.websocket\` package provide a standard API for building WebSocket endpoints, enabling real-time messaging between client and server.\n\n**Why this is asked :**\nInterviewers ask this to see if you know about modern communication patterns beyond HTTP.\n\n**Breaking it down :**\nWebSocket allows persistent connections, reducing overhead for real-time applications like chat, gaming, or live updates. Java EE provides annotations: \`@ServerEndpoint(\"/path\")\`, and methods annotated with \`@OnOpen\`, \`@OnMessage\`, \`@OnClose\`, \`@OnError\`. You can send messages via \`Session.getBasicRemote().sendText()\`.\n\n**How to structure your spoken answer :**\nDefine WebSocket and its advantages over HTTP for real-time. Explain the Java EE API with annotations. Give an example of a simple chat endpoint. Mention that WebSocket is part of the Java EE spec and is widely supported.\n\n**Follow-up angle to anticipate :**\nBe ready to discuss scaling WebSocket applications, session management, and fallbacks."],
  ["Advanced Java", "What is the difference between `WebSocket` and `HTTP/2`?", "websocket-vs-http2", "Compare WebSocket and HTTP/2.", "**Direct answer :**\nWebSocket provides full-duplex, long-lived connections for real-time communication. HTTP/2 is a protocol upgrade that improves performance via multiplexing and server push, but it is still request-response based. WebSocket is better for real-time bidirectional messaging, while HTTP/2 is better for regular web traffic with many requests.\n\n**Why this is asked :**\nInterviewers ask this to test your understanding of modern protocols and when to choose which.\n\n**Breaking it down :**\n- **WebSocket**: Persistent connection, low overhead after handshake, supports push from server at any time. Ideal for chat, gaming, financial tickers.\n- **HTTP/2**: Uses binary framing, multiplexing, server push, but still follows request-response semantics. Better for typical web page loading with many resources.\n\n**How to structure your spoken answer :**\nDefine each. Contrast the connection model (persistent vs request-response). Mention use cases. Note that WebSocket is built on HTTP/1.1 upgrade, while HTTP/2 is a separate protocol. Both can be used together.\n\n**Follow-up angle to anticipate :**\nBe ready to discuss how to choose between them and if they can be used together."],
  ["Advanced Java", "What is the purpose of `web.xml` in Java web applications?", "web-xml", "Explain web.xml.", "**Direct answer :**\n\`web.xml\` is the deployment descriptor for Java web applications. It defines servlet mappings, filters, listeners, welcome files, session timeout, and security constraints. In Servlet 3.0+, annotations can replace many entries.\n\n**Why this is asked :**\nInterviewers ask this to check if you know the configuration model of Java web apps.\n\n**Breaking it down :**\n\`web.xml\` is located in \`WEB-INF/\`. It is used to configure: servlets (\`<servlet>\` and \`<servlet-mapping>\`), filters, listeners, context parameters, error pages, session config, security roles, etc. With annotations like \`@WebServlet\`, \`@WebFilter\`, \`@WebListener\`, you can reduce XML. However, \`web.xml\` can still be used for overriding or external configuration.\n\n**How to structure your spoken answer :**\nDefine web.xml as a deployment descriptor. List common configurations. Mention the move to annotations but note that web.xml is still supported and sometimes necessary.\n\n**Follow-up angle to anticipate :**\nBe ready to discuss the order of loading and overriding of annotations vs web.xml."],
  ["Advanced Java", "What is a `MIME` type and how is it set in a servlet response?", "mime-type-servlet", "Explain MIME type in servlets.", "**Direct answer :**\nMIME type (Multipurpose Internet Mail Extensions) indicates the nature and format of a response. In a servlet, you set it using \`response.setContentType(\"text/html\")\` or \`response.setContentType(\"application/json\")\` etc., so the client knows how to process the response.\n\n**Why this is asked :**\nInterviewers ask this to check your understanding of response handling and content negotiation.\n\n**Breaking it down :**\nMIME types are used in HTTP to specify media types. In servlets, you call \`setContentType()\` before obtaining the \`PrintWriter\` or \`OutputStream\`. This sets the \`Content-Type\` header. Common types: text/html, application/json, image/png, etc.\n\n**How to structure your spoken answer :**\nDefine MIME type. Explain how to set it in servlet. Give examples for HTML, JSON, and file downloads. Mention that it helps browser or client interpret the response correctly.\n\n**Follow-up angle to anticipate :**\nBe ready to discuss how to handle file downloads with \`setContentType\` and \`setHeader\` for attachment."],
  ["Advanced Java", "How do you forward a request from a servlet to a JSP?", "servlet-forward", "Explain request forwarding.", "**Direct answer :**\nUse \`RequestDispatcher\` obtained from \`request.getRequestDispatcher(\"/page.jsp\")\` and then call \`forward(request, response)\`. This transfers the request to another resource (servlet or JSP) within the same web application, without client redirection.\n\n**Why this is asked :**\nInterviewers ask this to test your knowledge of the MVC pattern and request dispatching.\n\n**Breaking it down :**\n\`RequestDispatcher\` can be obtained via \`ServletRequest.getRequestDispatcher(String path)\` or \`ServletContext.getRequestDispatcher(String path)\`. The \`forward()\` method allows the target resource to process the request and produce the response. The client is unaware of the forward; the URL in the browser remains unchanged.\n\n**How to structure your spoken answer :**\nExplain the purpose: to delegate request processing. Show steps: get dispatcher, call forward. Mention the difference between forward and sendRedirect (forward is server-side, redirect is client-side).\n\n**Follow-up angle to anticipate :**\nBe ready to discuss when to use forward vs redirect, and how to pass attributes."],
  ["Advanced Java", "What is the difference between `forward` and `sendRedirect`?", "forward-vs-redirect", "Compare forward and sendRedirect.", "**Direct answer :**\n\`forward\` happens on the server side, without client involvement, and keeps the same request and URL. \`sendRedirect\` sends a 302 response to the client, causing a new request to the new URL, and changes the browser URL.\n\n**Why this is asked :**\nInterviewers ask this to check your understanding of request handling and navigation.\n\n**Breaking it down :**\n- **forward**: Server-side transfer, same request object (attributes preserved), fast, browser URL unchanged. Used for internal navigation (e.g., from servlet to JSP).\n- **sendRedirect**: Client-side redirection, new request (attributes lost unless stored in session or cookies), slower, browser URL changes. Used to redirect to external URLs or after POST to avoid duplicate submissions (POST-Redirect-GET pattern).\n\n**How to structure your spoken answer :**\nDefine both. Contrast based on location of transfer, request scope, URL change, and performance. Give typical use cases.\n\n**Follow-up angle to anticipate :**\nBe ready to discuss how to use both correctly in MVC."],

  // ==================== JDBC & DATABASE ACCESS (15) ====================
  ["Advanced Java", "What is JDBC and what are its main components?", "jdbc-overview", "Define JDBC and list its components.", "**Direct answer :**\nJDBC (Java Database Connectivity) is a Java API for connecting to relational databases. Its main components are: \`DriverManager\`, \`Connection\`, \`Statement\` (and its subtypes \`PreparedStatement\`, \`CallableStatement\`), \`ResultSet\`, and \`SQLException\`.\n\n**Why this is asked :**\nInterviewers ask this to check your understanding of database connectivity in Java, which is a fundamental skill.\n\n**Breaking it down :**\n- \`DriverManager\`: Manages JDBC drivers.\n- \`Connection\`: Represents a session with a specific database.\n- \`Statement\`: Used to execute SQL queries.\n- \`PreparedStatement\`: Precompiled SQL with parameters (prevents SQL injection).\n- \`CallableStatement\`: Used for stored procedures.\n- \`ResultSet\`: Holds the data returned from a query.\n- \`SQLException\`: Handles database errors.\n\n**How to structure your spoken answer :**\nStart with a definition of JDBC. List the core interfaces and classes, explaining their roles. Mention the typical flow: load driver, get connection, create statement, execute query, process result set, close resources.\n\n**Follow-up angle to anticipate :**\nBe ready to discuss the differences between Statement and PreparedStatement, and how to handle transactions."],
  ["Advanced Java", "What is the difference between `Statement` and `PreparedStatement`?", "statement-vs-preparedstatement", "Compare Statement and PreparedStatement.", "**Direct answer :**\n\`Statement\` is used for simple SQL without parameters, while \`PreparedStatement\` precompiles SQL with placeholders, improving performance and preventing SQL injection. \`PreparedStatement\` should be preferred for repeated queries or user input.\n\n**Why this is asked :**\nInterviewers ask this to test your knowledge of secure and efficient database access.\n\n**Breaking it down :**\n- \`Statement\`: Executes static SQL; concatenation of strings is error-prone and vulnerable to injection. No precompilation.\n- \`PreparedStatement\`: SQL with placeholders (\`?\`), precompiled, reuse with different parameters, prevents injection, better performance for repeated executions.\n\n**How to structure your spoken answer :**\nDefine both. Emphasize security and performance benefits of PreparedStatement. Give an example: \`PreparedStatement ps = conn.prepareStatement(\"SELECT * FROM users WHERE id = ?\");\` and then \`ps.setInt(1, userId);\`. Mention that PreparedStatement also handles date/timestamp formatting.\n\n**Follow-up angle to anticipate :**\nBe ready to discuss batch processing with PreparedStatement, and the use of \`CallableStatement\`."],
  ["Advanced Java", "How do you handle transactions in JDBC?", "jdbc-transactions", "Explain transaction handling.", "**Direct answer :**\nTransactions in JDBC are managed by setting auto-commit to \`false\` using \`connection.setAutoCommit(false)\`. Then, after executing operations, call \`connection.commit()\` to commit or \`connection.rollback()\` to rollback. This ensures atomicity.\n\n**Why this is asked :**\nInterviewers ask this to check your understanding of data consistency and atomic operations.\n\n**Breaking it down :**\nBy default, each statement is auto-committed. To group multiple statements into a transaction, disable auto-commit. After all successful statements, commit. If an exception occurs, rollback. You can also set savepoints for partial rollbacks. Transaction isolation levels can be set using \`connection.setTransactionIsolation()\`.\n\n**How to structure your spoken answer :**\nExplain the need for transactions. Describe the steps: setAutoCommit(false), execute, commit/rollback. Provide a try-catch block example. Mention that you must close resources in finally block, and ensure proper rollback on exception.\n\n**Follow-up angle to anticipate :**\nBe ready to discuss transaction isolation levels, distributed transactions (JTA), and Spring transaction management."],
  ["Advanced Java", "What is a `DataSource` and how does it differ from `DriverManager`?", "datasource-vs-drivermanager", "Compare DataSource and DriverManager.", "**Direct answer :**\n\`DriverManager\` is a basic JDBC driver management class. \`DataSource\` is a more advanced way to get connections, providing connection pooling and distributed transactions. \`DataSource\` is preferred in enterprise applications.\n\n**Why this is asked :**\nInterviewers ask this to test your knowledge of modern database connection management.\n\n**Breaking it down :**\n- \`DriverManager\`: Simple, but doesn't support connection pooling. Creating connections is expensive. It loads drivers statically. Not recommended for production.\n- \`DataSource\`: Provides connection pooling via implementations (e.g., Apache DBCP, HikariCP, Tomcat JDBC). Supports JTA for distributed transactions. Obtained via JNDI or programmatically. Improves performance and scalability.\n\n**How to structure your spoken answer :**\nDefine both. Explain that DataSource is the preferred way in Java EE and Spring. Mention that DataSource can be configured in application servers or via Spring Boot's auto-configuration. Note that DataSource provides pooling, which reduces overhead.\n\n**Follow-up angle to anticipate :**\nBe ready to discuss popular connection pool implementations and how to configure them in Spring Boot."],
  ["Advanced Java", "What is connection pooling and why is it used?", "connection-pooling", "Explain connection pooling.", "**Direct answer :**\nConnection pooling is a technique of reusing database connections to reduce the overhead of establishing new connections. It maintains a pool of connections that are reused, improving performance and resource utilization.\n\n**Why this is asked :**\nInterviewers ask this to check if you know performance optimization in database access.\n\n**Breaking it down :**\nCreating a database connection is expensive (network, authentication, memory). Connection pooling keeps a number of open connections in a pool. When a request needs a connection, it borrows one; when done, it returns it to the pool. Pooling also manages connection lifecycle, validation, and limits. Popular pools: HikariCP, Apache DBCP, C3P0.\n\n**How to structure your spoken answer :**\nDefine connection pooling. Explain the costs of new connections. Describe how pooling works. Mention that it is crucial for high-performance enterprise applications. Give examples of pool parameters: initial size, max size, timeout.\n\n**Follow-up angle to anticipate :**\nBe ready to discuss how to configure pooling in Spring Boot and how to monitor pool metrics."],
  ["Advanced Java", "What is the `ResultSet` and what are its types?", "resultset-types", "Explain ResultSet and its types.", "**Direct answer :**\n\`ResultSet\` represents the result of a SQL query. Its types are defined by sensitivity to changes and scrollability: \`TYPE_FORWARD_ONLY\`, \`TYPE_SCROLL_INSENSITIVE\`, \`TYPE_SCROLL_SENSITIVE\`, and concurrency modes: \`CONCUR_READ_ONLY\`, \`CONCUR_UPDATABLE\`.\n\n**Why this is asked :**\nInterviewers ask this to test your ability to process query results efficiently and handle updates.\n\n**Breaking it down :**\n- **Type**:\n  - \`TYPE_FORWARD_ONLY\`: cursor moves forward only (default).\n  - \`TYPE_SCROLL_INSENSITIVE\`: can scroll and navigate, but not sensitive to changes in database.\n  - \`TYPE_SCROLL_SENSITIVE\`: can scroll and reflects changes made by others.\n- **Concurrency**:\n  - \`CONCUR_READ_ONLY\`: cannot update.\n  - \`CONCUR_UPDATABLE\`: can update rows via ResultSet.\n\nYou specify these when creating the Statement: \`Connection.createStatement(type, concurrency)\`.\n\n**How to structure your spoken answer :**\nDefine ResultSet. Explain the scrollability and concurrency options. Mention that most applications use forward-only, read-only for simple queries. For scrollable or updatable, you need to consider performance.\n\n**Follow-up angle to anticipate :**\nBe ready to discuss how to use ResultSet for paging, and differences between JDBC drivers."],
  ["Advanced Java", "What is a `RowSet` and how does it differ from `ResultSet`?", "rowset-vs-resultset", "Compare RowSet and ResultSet.", "**Direct answer :**\n\`RowSet\` is an extension of \`ResultSet\` that adds features like being scrollable, updatable, serializable, and disconnected (e.g., \`CachedRowSet\`). It can be used without keeping a database connection open.\n\n**Why this is asked :**\nInterviewers ask this to see if you know about advanced result handling, especially for disconnected environments.\n\n**Breaking it down :**\n\`RowSet\` is a JavaBeans component that can be populated from a \`ResultSet\`. It can be disconnected (\`CachedRowSet\`) or connected (\`JdbcRowSet\`). Disconnected row sets are useful for client-server applications where the connection is not kept open. They can also be updated and the changes synchronized later.\n\n**How to structure your spoken answer :**\nDefine RowSet as an enhanced ResultSet. Contrast with ResultSet: RowSet is serializable, can be disconnected, and provides JavaBeans properties. Mention subinterfaces: JdbcRowSet, CachedRowSet, WebRowSet, FilteredRowSet, JoinRowSet. Give an example: using CachedRowSet to pass data to a remote client.\n\n**Follow-up angle to anticipate :**\nBe ready to discuss use cases for disconnected row sets and their limitations."],
  ["Advanced Java", "How do you call a stored procedure from JDBC?", "jdbc-stored-procedure", "Explain calling stored procedures.", "**Direct answer :**\nUse \`CallableStatement\` to call stored procedures. Prepare it with \`connection.prepareCall(\"{call proc_name(?,?)}\")\`, set parameters, and execute. Use \`registerOutParameter\` for output parameters.\n\n**Why this is asked :**\nInterviewers ask this to test your ability to interact with database procedures.\n\n**Breaking it down :**\n\`CallableStatement\` extends \`PreparedStatement\`. You use the syntax \`{call procedure_name(?, ?)}\` for procedures, or \`{? = call function_name(?, ?)}\` for functions. Set input parameters with \`setXXX()\`, register output parameters with \`registerOutParameter(index, type)\`, and execute with \`execute()\` or \`executeQuery()\`. Retrieve output parameters with \`getXXX()\`.\n\n**How to structure your spoken answer :**\nExplain that stored procedures are used for complex business logic in database. Show how to prepare CallableStatement. Provide an example with input and output parameters. Mention handling of result sets from procedures.\n\n**Follow-up angle to anticipate :**\nBe ready to discuss the performance implications and when to use stored procedures vs application logic."],
  ["Advanced Java", "What is the difference between `getString()` and `getObject()` in `ResultSet`?", "getstring-vs-getobject", "Compare getString and getObject.", "**Direct answer :**\n\`getString()\` returns the column value as a \`String\`, while \`getObject()\` returns it as an \`Object\`. \`getObject()\` is more flexible but requires explicit casting. \`getString()\` may apply database-specific conversions.\n\n**Why this is asked :**\nInterviewers ask this to check your understanding of type mapping in JDBC.\n\n**Breaking it down :**\n- \`getString()\`: Converts the column to a Java String, regardless of database type. Useful for portability.\n- \`getObject()\`: Returns the value as a Java Object, which can be a specific type (e.g., Integer, Date, Array). You can then cast. This avoids conversion overhead but requires knowledge of the column type.\n\n**How to structure your spoken answer :**\nExplain both methods. Mention that \`getString()\` is safe but may involve conversion; \`getObject()\` is more efficient if you need the exact type. Provide examples: \`rs.getString(1)\` vs \`rs.getObject(1, Integer.class)\` (JDBC 4.2+).\n\n**Follow-up angle to anticipate :**\nBe ready to discuss the \`getObject\` overload that takes a target type and how it simplifies mapping."],
  ["Advanced Java", "What is SQL injection and how can it be prevented in Java?", "sql-injection-prevention", "Explain SQL injection and prevention.", "**Direct answer :**\nSQL injection is a security vulnerability where an attacker injects malicious SQL code into input fields. It can be prevented by using \`PreparedStatement\` (with parameterized queries), escaping input, and using stored procedures.\n\n**Why this is asked :**\nInterviewers ask this to check your security awareness and safe coding practices.\n\n**Breaking it down :**\nSQL injection occurs when user input is concatenated directly into SQL strings. This can lead to data theft, deletion, or bypassing authentication. Prevention:\n- Use \`PreparedStatement\` with placeholders; the driver escapes input automatically.\n- Validate and sanitize inputs.\n- Use stored procedures (if they accept parameters).\n- Apply least privilege to database accounts.\n\n**How to structure your spoken answer :**\nDefine SQL injection. Show an example of vulnerable code (concatenation). Explain how \`PreparedStatement\` prevents it by treating input as data, not code. Mention other best practices.\n\n**Follow-up angle to anticipate :**\nBe ready to discuss ORM frameworks and how they handle SQL injection (e.g., JPA, Hibernate)."],

  // ==================== SPRING FRAMEWORK (25) ====================
  ["Advanced Java", "What is the Spring Framework and what are its main modules?", "spring-overview", "Define Spring and list its modules.", "**Direct answer :**\nSpring is a comprehensive framework for building enterprise Java applications. Its main modules are: Core Container (IoC, DI), AOP, Data Access (JDBC, ORM), Web (Spring MVC, WebFlux), Security, and Boot for microservices.\n\n**Why this is asked :**\nInterviewers ask this to gauge your overall knowledge of Spring and its capabilities.\n\n**Breaking it down :**\n- **Core Container**: \`spring-core\`, \`spring-beans\`, \`spring-context\` – provides IoC and DI.\n- **AOP**: \`spring-aop\` – aspect-oriented programming.\n- **Data Access**: \`spring-jdbc\`, \`spring-orm\`, \`spring-tx\` – transaction management and ORM integration.\n- **Web**: \`spring-web\`, \`spring-webmvc\`, \`spring-webflux\` – web layer, REST APIs, reactive.\n- **Security**: Spring Security – authentication and authorization.\n- **Boot**: Spring Boot – auto-configuration, starter dependencies, embedded servers.\n- **Cloud**: Spring Cloud – distributed systems patterns.\n\n**How to structure your spoken answer :**\nDefine Spring as a lightweight framework for enterprise Java. List the major modules, explaining the purpose of each. Mention that Spring Boot is built on top of Spring to simplify configuration.\n\n**Follow-up angle to anticipate :**\nBe ready to discuss the difference between Spring and Java EE, and why Spring is popular."],
  ["Advanced Java", "What is Inversion of Control (IoC) and Dependency Injection (DI)?", "ioc-di", "Explain IoC and DI.", "**Direct answer :**\nIoC (Inversion of Control) is a principle where the control of objects is transferred to a container. DI (Dependency Injection) is a pattern that implements IoC by injecting dependencies into a class from the outside, rather than the class creating them itself.\n\n**Why this is asked :**\nInterviewers ask this to test your understanding of the core concept of Spring.\n\n**Breaking it down :**\n- **IoC**: The framework (Spring container) manages object creation and lifecycle, rather than the application code. This decouples components.\n- **DI**: Dependencies are provided to a class (e.g., via constructor, setter, or field injection) by the container. This makes classes testable and flexible.\n\n**How to structure your spoken answer :**\nDefine IoC and DI. Explain that DI is the means to achieve IoC. Give an example: instead of \`new MyService()\`, you declare a bean and Spring injects it. Mention types of injection: constructor (preferred), setter, field.\n\n**Follow-up angle to anticipate :**\nBe ready to explain the advantages of DI (loose coupling, testability) and the different ways to configure beans (XML, annotations, Java config)."],
  ["Advanced Java", "What is a `Bean` in Spring?", "spring-bean", "Define Spring Bean.", "**Direct answer :**\nA Spring Bean is an object that is instantiated, assembled, and managed by the Spring IoC container. Beans are created based on configuration metadata (XML, annotations, or Java config).\n\n**Why this is asked :**\nInterviewers ask this to check your understanding of the core component of Spring.\n\n**Breaking it down :**\nBeans are the backbone of Spring applications. They are defined using \`@Component\`, \`@Service\`, \`@Repository\`, \`@Controller\`, or via XML \`<bean>\`. The container creates beans and wires them together. Beans have scopes (singleton, prototype, request, session) and lifecycle callbacks.\n\n**How to structure your spoken answer :**\nDefine a Bean as an object managed by Spring. Explain how to define beans. Mention the default scope (singleton). Give an example of a service class annotated with \`@Service\`.\n\n**Follow-up angle to anticipate :**\nBe ready to discuss bean scopes, lifecycle, and how to configure beans using \`@Configuration\` and \`@Bean\`."],
  ["Advanced Java", "What is the difference between `@Component`, `@Service`, `@Repository`, and `@Controller`?", "spring-stereotype-annotations", "Compare stereotype annotations.", "**Direct answer :**\nThey are all Spring stereotypes that register a class as a bean. \`@Component\` is generic; \`@Service\` is for service layer; \`@Repository\` for DAO layer (adds translation of persistence exceptions); \`@Controller\` for web controllers (with \`@ResponseBody\` for REST).\n\n**Why this is asked :**\nInterviewers ask this to check your knowledge of layer separation and Spring's special handling.\n\n**Breaking it down :**\n- \`@Component\`: generic stereotype for any Spring-managed bean.\n- \`@Service\`: indicates a service class (business logic). It's a specialization of \`@Component\`.\n- \`@Repository\`: for DAO/repository classes. It enables persistence exception translation (e.g., converting \`SQLException\` to Spring's \`DataAccessException\`).\n- \`@Controller\`: for web controllers (MVC). Often used with \`@RequestMapping\`.\n- \`@RestController\`: combines \`@Controller\` and \`@ResponseBody\`, for REST APIs.\n\n**How to structure your spoken answer :**\nExplain each annotation and its purpose. Mention that they are all \`@Component\` specializations, but convey the layer and enable additional features. Emphasize \`@Repository\`'s exception translation.\n\n**Follow-up angle to anticipate :**\nBe ready to discuss the use of \`@ControllerAdvice\` for exception handling."],
  ["Advanced Java", "What is the difference between constructor injection and setter injection?", "constructor-vs-setter-injection", "Compare injection types.", "**Direct answer :**\nConstructor injection uses the class constructor to inject dependencies, ensuring immutability and required dependencies. Setter injection uses setter methods, allowing optional dependencies and reconfiguration. Constructor injection is preferred for mandatory dependencies.\n\n**Why this is asked :**\nInterviewers ask this to test your best practices in DI.\n\n**Breaking it down :**\n- **Constructor**: Dependencies are provided via constructor parameters. Makes them immutable and thread-safe. Forces dependencies to be present. Works well with final fields. Encourages testability.\n- **Setter**: Uses setter methods. Allows optional dependencies (by not calling setter). Can cause circular dependencies (solved with setter). More verbose.\n\nSpring recommends constructor injection for mandatory dependencies.\n\n**How to structure your spoken answer :**\nDefine both. Explain the advantages: constructor for immutability, setter for optional. Mention that Spring 4.3+ can automatically infer constructor injection. Give examples. Conclude that constructor is preferred.\n\n**Follow-up angle to anticipate :**\nBe ready to discuss field injection (using \`@Autowired\` on fields) and why it's discouraged."],
  ["Advanced Java", "What is `@Autowired` and how does it work?", "autowired", "Explain @Autowired.", "**Direct answer :**\n\`@Autowired\` is a Spring annotation that marks a dependency for automatic injection. Spring looks for a bean of the required type and wires it. It can be applied to constructors, setters, fields, or methods.\n\n**Why this is asked :**\nInterviewers ask this to test your understanding of Spring's dependency injection mechanism.\n\n**Breaking it down :**\n- When Spring sees \`@Autowired\`, it injects a bean that matches the type (by default). If there are multiple candidates, \`@Qualifier\` can be used to specify a bean name.\n- It can be applied to fields (field injection), setters (setter injection), constructors (constructor injection), or any method.\n- Since Spring 4.3, if a class has a single constructor, \`@Autowired\` is optional.\n\n**How to structure your spoken answer :**\nDefine \`@Autowired\`. Explain how Spring resolves dependencies by type. Mention \`@Qualifier\` to resolve ambiguity. Give examples of use on constructor (preferred) and field. Note that constructor injection is recommended.\n\n**Follow-up angle to anticipate :**\nBe ready to discuss \`@Primary\` and \`@Qualifier\` in detail, and how to handle circular dependencies."],
  ["Advanced Java", "What is `@Qualifier` and when do you use it?", "qualifier", "Explain @Qualifier.", "**Direct answer :**\n\`@Qualifier\` is used alongside \`@Autowired\` to specify which bean to inject when multiple beans of the same type exist. You provide a qualifier name on the bean and the injection point.\n\n**Why this is asked :**\nInterviewers ask this to check your ability to handle ambiguous dependencies.\n\n**Breaking it down :**\nWhen there are multiple beans of the same type (e.g., multiple implementations of an interface), \`@Autowired\` alone would cause ambiguity. \`@Qualifier\` allows you to specify a bean by name or custom qualifier. You can define \`@Qualifier\` on bean definitions and on injection points.\n\n**How to structure your spoken answer :**\nExplain the problem: multiple beans of same type. Introduce \`@Qualifier\` as the solution. Give an example: \`@Qualifier(\"primary\")\` and \`@Qualifier(\"secondary\")\` for two data sources. Mention that you can create custom qualifier annotations.\n\n**Follow-up angle to anticipate :**\nBe ready to discuss \`@Primary\` as an alternative, and the use of \`@Qualifier\` with \`@Autowired\` on constructors."],
  ["Advanced Java", "What is the difference between `@Configuration` and `@Component`?", "configuration-vs-component", "Compare @Configuration and @Component.", "**Direct answer :**\n\`@Configuration\` indicates a class that declares beans using \`@Bean\` methods. It is a Spring-managed bean but with special behavior: it is proxied to ensure \`@Bean\` methods return singleton beans. \`@Component\` is a generic stereotype for any bean.\n\n**Why this is asked :**\nInterviewers ask this to check your understanding of Spring's bean definition and proxy mechanisms.\n\n**Breaking it down :**\n- \`@Configuration\`: Used with \`@Bean\` to define beans programmatically. The class is a bean itself. The container ensures that \`@Bean\` methods are enhanced to honor singleton scope (CGLIB proxying).\n- \`@Component\`: Marks a class as a bean, discovered via component scanning. It doesn't have the proxy enhancement for \`@Bean\` methods (though you can still use \`@Bean\` inside a \`@Component\` but it won't be proxied).\n\n**How to structure your spoken answer :**\nDefine both. Explain that \`@Configuration\` is for configuration classes, \`@Component\` for general components. Mention that \`@Configuration\` classes are proxied, which ensures singleton behavior for \`@Bean\` methods. Give an example: \`@Configuration\` with \`@Bean\` for data source.\n\n**Follow-up angle to anticipate :**\nBe ready to discuss the difference between \`@Component\` and \`@Configuration\` in terms of inter-bean references."],
  ["Advanced Java", "What is the Spring `ApplicationContext`?", "applicationcontext", "Explain ApplicationContext.", "**Direct answer :**\n\`ApplicationContext\` is the Spring IoC container that manages beans, provides configuration, and supports internationalization, event propagation, and resource loading. It is an extension of \`BeanFactory\`.\n\n**Why this is asked :**\nInterviewers ask this to test your understanding of the container and its capabilities.\n\n**Breaking it down :**\n\`ApplicationContext\` is the central interface in Spring. Its implementations include \`ClassPathXmlApplicationContext\`, \`FileSystemXmlApplicationContext\`, \`AnnotationConfigApplicationContext\` (for Java config), and \`WebApplicationContext\` (for web apps). It provides:\n- Bean management (instantiation, wiring, lifecycle)\n- AOP proxy support\n- Resource loading\n- Event propagation\n- Internationalization (i18n)\n- Environment abstraction\n\n**How to structure your spoken answer :**\nDefine \`ApplicationContext\` as the Spring container. Mention its advantages over \`BeanFactory\` (more features). List common implementations. Explain that in Spring Boot, \`SpringApplication.run()\` creates an \`ApplicationContext\`.\n\n**Follow-up angle to anticipate :**\nBe ready to discuss \`BeanFactory\` vs \`ApplicationContext\`, and how to access the context in a web app."],
  ["Advanced Java", "What is Aspect-Oriented Programming (AOP) in Spring?", "spring-aop", "Explain AOP in Spring.", "**Direct answer :**\nAOP (Aspect-Oriented Programming) allows separating cross-cutting concerns (logging, security, transaction management) from business logic. In Spring, AOP is implemented using proxies and aspects, with advice (before, after, around) applied to join points (method executions).\n\n**Why this is asked :**\nInterviewers ask this to test your understanding of modularizing cross-cutting concerns.\n\n**Breaking it down :**\n- **Aspect**: A module of cross-cutting concern (e.g., logging aspect).\n- **Join point**: A point in the execution (e.g., method call).\n- **Advice**: Action taken at a join point (before, after, around).\n- **Pointcut**: Expression that matches join points.\n- **Weaving**: Integrating aspects with the target object.\n\nSpring AOP uses proxies (JDK dynamic proxies or CGLIB) to apply advice. It supports declarative transaction management and security.\n\n**How to structure your spoken answer :**\nDefine AOP and its purpose. Explain key terms. Mention that Spring AOP is proxy-based and works with method execution join points. Give an example: using \`@Transactional\` or \`@Around\` for logging. Mention that you can define aspects with \`@Aspect\`.\n\n**Follow-up angle to anticipate :**\nBe ready to discuss the differences between Spring AOP and AspectJ, and when to use each."],
  ["Advanced Java", "What is `@Transactional` and how does it work?", "transactional", "Explain @Transactional.", "**Direct answer :**\n\`@Transactional\` is a Spring annotation that declares transactional boundaries for a method or class. It uses AOP to start a transaction before the method and commit/rollback after. It supports propagation, isolation, timeout, and read-only settings.\n\n**Why this is asked :**\nInterviewers ask this to test your knowledge of Spring's declarative transaction management.\n\n**Breaking it down :**\n- \`@Transactional\` can be applied to methods or classes.\n- Spring creates a proxy that handles transaction management.\n- Attributes: \`propagation\` (REQUIRED, REQUIRES_NEW, etc.), \`isolation\` (READ_COMMITTED, etc.), \`timeout\`, \`readOnly\`, \`rollbackFor\`.\n- By default, it rolls back on \`RuntimeException\` and \`Error\`, not on checked exceptions.\n- It requires a \`PlatformTransactionManager\` (e.g., \`DataSourceTransactionManager\` for JDBC, \`JpaTransactionManager\` for JPA).\n\n**How to structure your spoken answer :**\nDefine \`@Transactional\`. Explain that it uses AOP. Mention key attributes and their meanings. Give an example of using it on a service method. Note that it should be applied to public methods.\n\n**Follow-up angle to anticipate :**\nBe ready to discuss propagation types, self-invocation issues, and transaction management with multiple data sources."],
  ["Advanced Java", "What is the difference between `@Controller` and `@RestController`?", "controller-vs-restcontroller", "Compare @Controller and @RestController.", "**Direct answer :**\n\`@Controller\` is used to define a controller for MVC, where methods return view names. \`@RestController\` is a convenience annotation that combines \`@Controller\` and \`@ResponseBody\`, indicating that each method returns a domain object (JSON/XML) directly, not a view.\n\n**Why this is asked :**\nInterviewers ask this to test your knowledge of building REST APIs with Spring.\n\n**Breaking it down :**\n- \`@Controller\`: Traditional Spring MVC controller, returns model and view name. You need to add \`@ResponseBody\` on methods to return data directly.\n- \`@RestController\`: Since Spring 4.0, shorthand for \`@Controller\` + \`@ResponseBody\` on all methods. Ideal for RESTful web services.\n\n**How to structure your spoken answer :**\nDefine both. Explain the difference in return types. Mention that \`@RestController\` is preferred for REST APIs. Give an example: \`@RestController\` method returns \`User\` object, automatically serialized to JSON.\n\n**Follow-up angle to anticipate :**\nBe ready to discuss how to configure message converters and handle exception responses."],
  ["Advanced Java", "What is the purpose of `@RequestMapping` and its variants?", "requestmapping", "Explain @RequestMapping.", "**Direct answer :**\n\`@RequestMapping\` is used to map HTTP requests to handler methods in Spring MVC. Variants like \`@GetMapping\`, \`@PostMapping\`, \`@PutMapping\`, \`@DeleteMapping\`, \`@PatchMapping\` are convenience annotations for specific HTTP methods.\n\n**Why this is asked :**\nInterviewers ask this to check your understanding of routing in Spring MVC.\n\n**Breaking it down :**\n- \`@RequestMapping\` can be used at class level to set base URL, and at method level to refine mapping. It supports attributes: \`path\`, \`method\`, \`params\`, \`headers\`, \`consumes\`, \`produces\`.\n- Specific method annotations: \`@GetMapping\` = \`@RequestMapping(method=GET)\`, \`@PostMapping\` = \`@RequestMapping(method=POST)\`, etc. They are more readable.\n\n**How to structure your spoken answer :**\nDefine \`@RequestMapping\`. List its variants and their HTTP method mapping. Explain how to use it to handle different endpoints. Give an example: \`@GetMapping(\"/users/{id}\")\`.\n\n**Follow-up angle to anticipate :**\nBe ready to discuss advanced mapping (path variables, request parameters, headers) and content negotiation."],
  ["Advanced Java", "What is `@PathVariable` and `@RequestParam`?", "pathvariable-requestparam", "Explain @PathVariable and @RequestParam.", "**Direct answer :**\n\`@PathVariable\` extracts values from the URI template (e.g., \`/users/{id}\`). \`@RequestParam\` extracts query parameters from the request string (e.g., \`?name=John\`).\n\n**Why this is asked :**\nInterviewers ask this to test your ability to handle different types of input in controllers.\n\n**Breaking it down :**\n- \`@PathVariable\`: Binds the value of a URI variable to a method parameter. Example: \`@GetMapping(\"/users/{userId}\")\` and method parameter \`@PathVariable Long userId\`.\n- \`@RequestParam\`: Binds a query parameter or form data. Example: \`@GetMapping(\"/users\")\` and \`@RequestParam String name\`. Supports required, defaultValue.\n\n**How to structure your spoken answer :**\nDefine both. Give examples. Explain when to use each: path variables for resource identifiers, request parameters for filtering or optional data. Mention that both can be optional.\n\n**Follow-up angle to anticipate :**\nBe ready to discuss \`@RequestHeader\`, \`@RequestBody\`, and \`@ModelAttribute\`."],
  ["Advanced Java", "What is the Spring Boot and its advantages?", "spring-boot", "Define Spring Boot.", "**Direct answer :**\nSpring Boot is a project built on Spring that simplifies application setup and development. It provides auto-configuration, starter dependencies, embedded servers, and production-ready features (actuator, metrics). It reduces boilerplate and configuration.\n\n**Why this is asked :**\nInterviewers ask this to see if you're familiar with modern Spring development.\n\n**Breaking it down :**\n- **Auto-configuration**: Automatically configures Spring beans based on classpath dependencies.\n- **Starters**: Dependency descriptors that simplify inclusion of common libraries (e.g., \`spring-boot-starter-web\`).\n- **Embedded servers**: Tomcat, Jetty, or Undertow are included, so you can run as a JAR.\n- **Production features**: Actuator provides endpoints for health, metrics, and monitoring.\n- **DevTools**: Hot reload for development.\n\n**How to structure your spoken answer :**\nDefine Spring Boot. Highlight its main advantages: rapid development, less configuration, auto-configuration, embedded server, production-ready features. Compare to traditional Spring.\n\n**Follow-up angle to anticipate :**\nBe ready to discuss how to customize auto-configuration, and the \`@SpringBootApplication\` annotation."],
  ["Advanced Java", "What is `@SpringBootApplication`?", "springbootapplication", "Explain @SpringBootApplication.", "**Direct answer :**\n\`@SpringBootApplication\` is a convenience annotation that combines \`@Configuration\`, \`@EnableAutoConfiguration\`, and \`@ComponentScan\`. It is typically placed on the main class of a Spring Boot application.\n\n**Why this is asked :**\nInterviewers ask this to test your knowledge of the entry point of a Spring Boot app.\n\n**Breaking it down :**\n- \`@Configuration\`: Marks the class as a source of bean definitions.\n- \`@EnableAutoConfiguration\`: Enables Spring Boot's auto-configuration.\n- \`@ComponentScan\`: Enables scanning for components in the current package and sub-packages.\n\n**How to structure your spoken answer :**\nDefine \`@SpringBootApplication\`. Explain what it composes. Mention that it's used on the main class with \`SpringApplication.run()\`. Give an example.\n\n**Follow-up angle to anticipate :**\nBe ready to discuss how to exclude specific auto-configuration and the effect of \`@ComponentScan\`."],
  ["Advanced Java", "What is Spring Data JPA and how does it differ from JPA?", "spring-data-jpa", "Explain Spring Data JPA.", "**Direct answer :**\nSpring Data JPA is a Spring module that provides repository support for JPA. It reduces boilerplate code by generating implementations for repository interfaces. It differs from JPA by adding a higher-level abstraction, including query methods, pagination, and auditing.\n\n**Why this is asked :**\nInterviewers ask this to see if you know how to efficiently implement data access layers.\n\n**Breaking it down :**\n- **JPA**: Specification for ORM in Java; requires implementation (Hibernate, EclipseLink).\n- **Spring Data JPA**: Provides \`Repository\` interface hierarchy (\`JpaRepository\`, \`CrudRepository\`, \`PagingAndSortingRepository\`). It automatically implements CRUD methods based on naming conventions (\`findBy...\`), supports \`@Query\` for custom JPQL, and provides pagination and sorting.\n\n**How to structure your spoken answer :**\nDefine Spring Data JPA. Explain that it sits on top of JPA, simplifying data access. Contrast with plain JPA (more boilerplate). Mention core interfaces and query derivation. Give an example: \`UserRepository extends JpaRepository<User, Long>\`.\n\n**Follow-up angle to anticipate :**\nBe ready to discuss custom queries with \`@Query\`, and the difference between \`JpaRepository\` and \`CrudRepository\`."],
  ["Advanced Java", "What is `@Entity` and `@Table` in JPA?", "entity-table-jpa", "Explain JPA annotations.", "**Direct answer :**\n\`@Entity\` marks a Java class as a JPA entity (maps to a database table). \`@Table\` is optional and specifies the table name and schema. \`@Id\` defines the primary key.\n\n**Why this is asked :**\nInterviewers ask this to test your basic JPA mapping knowledge.\n\n**Breaking it down :**\n- \`@Entity\`: Indicates that the class is an entity and should be managed by the persistence context.\n- \`@Table\`: Specifies the table name if different from the class name. Can also define unique constraints, indexes.\n- \`@Id\`: Designates the primary key.\n- \`@GeneratedValue\`: Defines primary key generation strategy.\n\n**How to structure your spoken answer :**\nDefine the annotations. Explain that \`@Entity\` is mandatory, \`@Table\` is optional. Mention other common annotations: \`@Column\`, \`@OneToMany\`, etc. Give an example of a simple entity.\n\n**Follow-up angle to anticipate :**\nBe ready to discuss mapping relationships and cascade options."],
  ["Advanced Java", "What are the different relationship mappings in JPA?", "jpa-relationships", "Explain JPA relationships.", "**Direct answer :**\nJPA supports four relationship types: \`@OneToOne\`, \`@OneToMany\`, \`@ManyToOne\`, and \`@ManyToMany\`. They define how entities relate to each other, and you can specify fetch type (LAZY/EAGER) and cascade options.\n\n**Why this is asked :**\nInterviewers ask this to check your ability to model database relationships in Java.\n\n**Breaking it down :**\n- \`@OneToOne\`: A single entity refers to another single entity.\n- \`@OneToMany\`/\`@ManyToOne\`: Bidirectional or unidirectional one-to-many and many-to-one.\n- \`@ManyToMany\`: Many-to-many relationship, often with a join table.\n- Fetch types: LAZY (default for collections), EAGER (default for single references). Use LAZY to avoid performance issues.\n- Cascade: operations like PERSIST, MERGE, REMOVE, ALL.\n\n**How to structure your spoken answer :**\nList the relationship types. Explain each with examples. Discuss fetch and cascade. Mention the importance of choosing appropriate fetch strategy.\n\n**Follow-up angle to anticipate :**\nBe ready to discuss the difference between owning side and inverse side, and how to map join columns."],
  ["Advanced Java", "What is the difference between `@ManyToOne` and `@OneToMany`?", "manytoone-vs-onetomany", "Compare @ManyToOne and @OneToMany.", "**Direct answer :**\n\`@ManyToOne\` defines a many-to-one relationship from the child entity to the parent entity. \`@OneToMany\` defines a one-to-many relationship from the parent to the children. They are often used together as a bidirectional relationship.\n\n**Why this is asked :**\nInterviewers ask this to check your understanding of bidirectional mapping and ownership.\n\n**Breaking it down :**\n- \`@ManyToOne\`: Usually on the child side, with \`@JoinColumn\` to specify foreign key.\n- \`@OneToMany\`: Usually on the parent side, with \`mappedBy\` attribute to point to the field on the child side that maps the relationship.\n- The side with \`@ManyToOne\` is typically the owning side; the \`@OneToMany\` side uses \`mappedBy\` to indicate it's the inverse side.\n\n**How to structure your spoken answer :**\nDefine both. Explain that they represent inverse directions. Give an example: \`Order\` has \`@OneToMany\` to \`OrderItem\`, and \`OrderItem\` has \`@ManyToOne\` to \`Order\`. Mention that \`mappedBy\` indicates the inverse side.\n\n**Follow-up angle to anticipate :**\nBe ready to discuss the \`@JoinColumn\` annotation and how to handle lazy loading."],
  ["Advanced Java", "What is the Spring Security framework?", "spring-security", "Explain Spring Security.", "**Direct answer :**\nSpring Security is a powerful framework that provides authentication, authorization, and other security features for Java applications. It integrates with Spring and supports various authentication mechanisms (LDAP, OAuth2, JWT, form login, etc.).\n\n**Why this is asked :**\nInterviewers ask this to test your knowledge of securing enterprise applications.\n\n**Breaking it down :**\n- **Authentication**: Verifying user identity.\n- **Authorization**: Determining if a user has permission to access a resource.\n- **Features**: CSRF protection, session management, method-level security, password encoding, etc.\n- **Configuration**: Via \`WebSecurityConfigurerAdapter\` (or \`SecurityFilterChain\` in newer versions) to define rules.\n\n**How to structure your spoken answer :**\nDefine Spring Security. Mention its core features. Explain how to integrate with Spring Boot (using starters). Give a simple example of basic authentication setup. Mention that it uses a filter chain.\n\n**Follow-up angle to anticipate :**\nBe ready to discuss OAuth2, JWT, and the difference between authentication and authorization."],
  ["Advanced Java", "What is JWT and how is it used with Spring Security?", "jwt-spring-security", "Explain JWT in Spring Security.", "**Direct answer :**\nJWT (JSON Web Token) is a compact, URL-safe token format for securely transmitting claims between parties. In Spring Security, JWT is used for stateless authentication: the client sends the token in the \`Authorization\` header, and Spring Security validates it via a filter.\n\n**Why this is asked :**\nInterviewers ask this to check if you know modern stateless authentication mechanisms.\n\n**Breaking it down :**\n- JWT consists of header, payload (claims), and signature. It is self-contained and can carry user info.\n- In Spring Security, you can implement a \`OncePerRequestFilter\` that extracts the JWT, validates it, and sets the \`Authentication\` in the \`SecurityContext\`.\n- You can use libraries like \`jjwt\` or \`Nimbus JOSE\`.\n- Typically used for REST APIs where session is not needed.\n\n**How to structure your spoken answer :**\nDefine JWT. Explain its structure. Describe how to integrate with Spring Security: create a filter, validate token, set authentication. Mention that it's stateless, so no session storage. Provide an example of using \`@EnableWebSecurity\` and configuring the filter chain.\n\n**Follow-up angle to anticipate :**\nBe ready to discuss token expiration, refresh tokens, and security considerations."],
  ["Advanced Java", "What is OAuth2 and how does Spring Security support it?", "oauth2-spring", "Explain OAuth2 in Spring.", "**Direct answer :**\nOAuth2 is an authorization framework that allows third-party applications to get limited access to user resources. Spring Security provides OAuth2 client and resource server support, enabling integration with OAuth2 providers (Google, GitHub) and implementing authorization servers.\n\n**Why this is asked :**\nInterviewers ask this to check your knowledge of modern authorization protocols.\n\n**Breaking it down :**\n- **OAuth2 roles**: Resource Owner, Client, Authorization Server, Resource Server.\n- **Grant types**: Authorization Code, Implicit, Password, Client Credentials.\n- Spring Security offers \`spring-security-oauth2-client\` for client-side, \`spring-security-oauth2-resource-server\` for protecting APIs, and \`spring-security-oauth2-authorization-server\` (standalone) for auth server.\n- Configuration: properties in \`application.yml\` for client registration, and \`@EnableResourceServer\` (deprecated) or \`@EnableWebSecurity\` with \`oauth2ResourceServer()\`.\n\n**How to structure your spoken answer :**\nDefine OAuth2 and its purpose. Explain how Spring Security integrates it. Mention the different roles and grant types. Describe how to configure an OAuth2 client and resource server. Touch on the shift to Spring Security 5 for OAuth2.\n\n**Follow-up angle to anticipate :**\nBe ready to discuss the differences between OAuth2 and JWT, and how to implement an authorization server."],
  ["Advanced Java", "What is the Spring Cloud project?", "spring-cloud", "Explain Spring Cloud.", "**Direct answer :**\nSpring Cloud provides tools for building distributed systems and microservices. It includes modules for service discovery (Eureka), configuration management (Config Server), API gateway (Gateway), circuit breaker (Resilience4j), and distributed tracing (Sleuth).\n\n**Why this is asked :**\nInterviewers ask this to check your understanding of microservices architecture.\n\n**Breaking it down :**\n- **Service Discovery**: Eureka, Consul, Zookeeper.\n- **Configuration**: Spring Cloud Config Server for externalized configuration.\n- **Gateway**: Spring Cloud Gateway (replaces Zuul).\n- **Resilience**: Resilience4j (circuit breaker, retry, rate limiter).\n- **Tracing**: Sleuth with Zipkin for distributed tracing.\n- **Messaging**: Spring Cloud Stream.\n\n**How to structure your spoken answer :**\nDefine Spring Cloud as a suite of tools for microservices. List key modules and their purposes. Mention that it builds on Spring Boot. Give an example: using Eureka for service registration, Gateway for routing, and Config for external properties.\n\n**Follow-up angle to anticipate :**\nBe ready to discuss the difference between Spring Cloud and Kubernetes, and how they complement."],
  ["Advanced Java", "What is a `Circuit Breaker` pattern and how is it implemented in Spring Cloud?", "circuit-breaker-spring-cloud", "Explain circuit breaker in Spring Cloud.", "**Direct answer :**\nThe Circuit Breaker pattern prevents cascading failures by stopping requests to a failing service. In Spring Cloud, it is implemented using Resilience4j (or Hystrix, which is deprecated). It provides fallback mechanisms and monitors failure rates to open/close the circuit.\n\n**Why this is asked :**\nInterviewers ask this to test your knowledge of resilience in microservices.\n\n**Breaking it down :**\n- When a service call fails repeatedly, the circuit breaker trips (open), and subsequent calls are short-circuited to a fallback method.\n- After a timeout, the circuit goes to half-open, allowing a limited number of test requests to check if the service is recovered.\n- In Spring Cloud, you can use \`@CircuitBreaker\` from Resilience4j or \`@HystrixCommand\` (legacy).\n- Configuration: define failure rate, wait duration, etc.\n\n**How to structure your spoken answer :**\nDefine the Circuit Breaker pattern. Explain its states (closed, open, half-open). Describe how it prevents cascading failures. Mention Resilience4j as the recommended implementation in Spring Cloud. Give an example of annotating a method with \`@CircuitBreaker\` and providing a fallback.\n\n**Follow-up angle to anticipate :**\nBe ready to discuss other resilience patterns: retry, bulkhead, rate limiter."],
  ["Advanced Java", "What is the Spring `@Value` annotation?", "value-annotation", "Explain @Value.", "**Direct answer :**\n\`@Value\` is used to inject values from properties files, environment variables, or other sources into Spring beans. It supports SpEL (Spring Expression Language) for complex expressions.\n\n**Why this is asked :**\nInterviewers ask this to check your ability to externalize configuration.\n\n**Breaking it down :**\n- You can use \`@Value\` on fields, constructors, or methods.\n- It can inject simple values: \`@Value(\"${property.key}\")\`.\n- It can inject default values: \`@Value(\"${property.key:default}\")\`.\n- It can inject system properties, environment variables, and even SpEL expressions like \`#{systemProperties['user.name']}\`.\n- Works with property sources (application.properties, YAML).\n\n**How to structure your spoken answer :**\nDefine \`@Value\`. Explain its usage with \`@PropertySource\` or \`application.properties\`. Give examples: injecting a string, a number, a list (via SpEL). Mention that for complex objects, \`@ConfigurationProperties\` is preferred.\n\n**Follow-up angle to anticipate :**\nBe ready to discuss \`@ConfigurationProperties\` and when to use it over \`@Value\`."],
  ["Advanced Java", "What is the difference between `@ConfigurationProperties` and `@Value`?", "configprops-vs-value", "Compare @ConfigurationProperties and @Value.", "**Direct answer :**\n\`@ConfigurationProperties\` binds external properties to a Java bean in a type-safe way, supporting complex structures. \`@Value\` injects individual values. \`@ConfigurationProperties\` is preferred for grouping related settings.\n\n**Why this is asked :**\nInterviewers ask this to test your knowledge of configuration management.\n\n**Breaking it down :**\n- \`@ConfigurationProperties\`: Maps properties with a common prefix to fields of a POJO. Supports validation, nested properties, and lists. Provides type safety and structured configuration.\n- \`@Value\`: Injects single values, supports SpEL, good for simple or one-off values.\n\n**How to structure your spoken answer :**\nExplain both. Contrast them: \`@ConfigurationProperties\` for complex objects, \`@Value\` for simple values. Mention that \`@ConfigurationProperties\` can be validated with \`@Validated\`. Give an example: \`@ConfigurationProperties(prefix = \"app\")\` to map \`app.name\` and \`app.port\`.\n\n**Follow-up angle to anticipate :**\nBe ready to discuss how to enable \`@ConfigurationProperties\` and the use of \`@EnableConfigurationProperties\`."],

  // ==================== HIBERNATE & JPA (15) ====================
  ["Advanced Java", "What is Hibernate and how does it relate to JPA?", "hibernate-vs-jpa", "Explain Hibernate and JPA.", "**Direct answer :**\nHibernate is an ORM (Object-Relational Mapping) framework that implements the JPA specification. JPA is a standard specification, while Hibernate is an implementation that provides additional features beyond the standard.\n\n**Why this is asked :**\nInterviewers ask this to test your understanding of the relationship between the standard and the implementation.\n\n**Breaking it down :**\n- **JPA**: Java Persistence API (now Jakarta Persistence) – a standard for ORM. It defines interfaces and annotations.\n- **Hibernate**: A popular JPA implementation. It also offers proprietary extensions (e.g., HQL, Criteria API, caching).\n- You can use Hibernate directly (with \`SessionFactory\`) or via JPA (with \`EntityManager\`).\n\n**How to structure your spoken answer :**\nDefine JPA as a specification. Define Hibernate as an implementation. Mention that Hibernate extends JPA with extra features. Emphasize that using JPA APIs allows switching implementations, but Hibernate is the most common.\n\n**Follow-up angle to anticipate :**\nBe ready to discuss the differences between Hibernate and other JPA providers (EclipseLink, OpenJPA)."],
  ["Advanced Java", "What is the difference between `Session` and `EntityManager`?", "session-vs-entitymanager", "Compare Session and EntityManager.", "**Direct answer :**\n\`Session\` is the core Hibernate API for persistence operations; \`EntityManager\` is the JPA standard interface. Both serve similar purposes but \`EntityManager\` is portable across JPA implementations, while \`Session\` provides Hibernate-specific features.\n\n**Why this is asked :**\nInterviewers ask this to test your knowledge of Hibernate vs JPA usage.\n\n**Breaking it down :**\n- \`Session\`: Hibernate's native interface, obtained from \`SessionFactory\`. It provides methods like \`save()\`, \`update()\`, \`delete()\`, \`createQuery()\` using HQL.\n- \`EntityManager\`: JPA interface, obtained from \`EntityManagerFactory\`. Methods: \`persist()\`, \`merge()\`, \`remove()\`, \`find()\`, \`createQuery()\` using JPQL.\n- Hibernate \`Session\` can be unwrapped from \`EntityManager\` to access Hibernate-specific features.\n\n**How to structure your spoken answer :**\nDefine both. Explain that \`EntityManager\` is JPA standard, \`Session\` is Hibernate-specific. Mention that in Spring Data JPA, you typically use \`EntityManager\`. Note that \`Session\` has some extra features like \`evict()\`, \`replicate()\`. Conclude that using JPA is preferred for portability.\n\n**Follow-up angle to anticipate :**\nBe ready to discuss the relationship between \`SessionFactory\` and \`EntityManagerFactory\`."],
  ["Advanced Java", "What is the difference between `get()` and `load()` in Hibernate?", "get-vs-load-hibernate", "Compare get() and load().", "**Direct answer :**\n\`get()\` immediately loads the entity and returns null if not found. \`load()\` returns a proxy and throws an exception if the entity is not found. \`load()\` is lazy and can improve performance.\n\n**Why this is asked :**\nInterviewers ask this to test your understanding of lazy loading and proxy objects.\n\n**Breaking it down :**\n- \`session.get(Class, id)\`: Hits the database immediately, returns the entity or null. Useful when you need the data right away.\n- \`session.load(Class, id)\`: Returns a proxy without hitting DB. The proxy will be initialized when accessed. If the entity doesn't exist, a \`ObjectNotFoundException\` is thrown later. Useful when you only need a reference (e.g., to set a relationship) and don't want to hit DB.\n\n**How to structure your spoken answer :**\nDefine both methods. Contrast their behavior regarding DB access and exception handling. Explain use cases: \`get()\` when you need the actual data; \`load()\` when you only need a proxy for association. Mention performance implications.\n\n**Follow-up angle to anticipate :**\nBe ready to discuss the concept of proxy and lazy initialization exceptions."],
  ["Advanced Java", "What is the difference between `save()` and `persist()` in Hibernate?", "save-vs-persist", "Compare save() and persist().", "**Direct answer :**\n\`save()\` is a Hibernate-specific method that returns the generated identifier immediately. \`persist()\` is a JPA method that doesn't guarantee immediate identifier generation and is transactional.\n\n**Why this is asked :**\nInterviewers ask this to test your knowledge of Hibernate vs JPA methods.\n\n**Breaking it down :**\n- \`session.save(Object)\`: Hibernate method, returns the generated ID. It may execute an INSERT immediately or flush later, but it returns the ID.\n- \`entityManager.persist(Object)\`: JPA method, makes the entity managed. The ID may not be assigned until flush. It's part of the JPA spec.\n- In Hibernate, \`save()\` is not part of JPA; if you use JPA, use \`persist()\`.\n\n**How to structure your spoken answer :**\nDefine both. Explain that \`save()\` is Hibernate-specific, returns ID; \`persist()\` is JPA, doesn't return ID. Mention that \`persist()\` is preferred in JPA environments. Also note that \`save()\` can be used with Hibernate's \`Session\`.\n\n**Follow-up angle to anticipate :**\nBe ready to discuss \`merge()\` and \`update()\` as well."],
  ["Advanced Java", "What is the difference between `update()` and `merge()`?", "update-vs-merge-hibernate", "Compare update() and merge().", "**Direct answer :**\n\`update()\` reattaches a detached entity to the session and forces an update. \`merge()\` copies state from a detached entity to a managed entity (or creates a new one), and returns the managed instance.\n\n**Why this is asked :**\nInterviewers ask this to test your understanding of detached entities and state management.\n\n**Breaking it down :**\n- \`session.update(entity)\`: Reattaches the entity to the current session. If the entity has been modified, it will be updated at flush. Throws exception if another entity with same ID is already in session.\n- \`session.merge(entity)\`: Copies the state of the detached entity to a new or existing managed instance. Returns the managed instance. Does not modify the detached object. Safer to avoid conflicts.\n\n**How to structure your spoken answer :**\nDefine both. Explain the scenario: detached entity. Contrast behavior: \`update\` reattaches, \`merge\` copies. Mention that \`merge\` is safer and recommended when you're not sure if the entity is managed.\n\n**Follow-up angle to anticipate :**\nBe ready to discuss the use of \`saveOrUpdate()\` and when to use each."],
  ["Advanced Java", "What is the difference between `FlushMode` types in Hibernate?", "flushmode", "Explain FlushMode.", "**Direct answer :**\n\`FlushMode\` determines when Hibernate flushes the session (synchronizes with DB). Options: \`AUTO\` (default – flush before query execution), \`COMMIT\` (flush only on commit), and \`MANUAL\` (manual flush).\n\n**Why this is asked :**\nInterviewers ask this to test your understanding of session synchronization and performance.\n\n**Breaking it down :**\n- \`AUTO\`: Flush before any query if there are pending changes, to ensure query results are up-to-date. Can lead to unnecessary flushes.\n- \`COMMIT\`: Flush only when committing the transaction. Better performance but query results may be stale if changes haven't been flushed.\n- \`MANUAL\`: You must call \`session.flush()\` explicitly.\n\n**How to structure your spoken answer :**\nDefine FlushMode. Explain the options and their trade-offs. Mention that \`AUTO\` is default, but \`COMMIT\` can improve performance when you know you won't query changed data.\n\n**Follow-up angle to anticipate :**\nBe ready to discuss how to set FlushMode and the impact on performance."],
  ["Advanced Java", "What are the different caching levels in Hibernate?", "hibernate-caching", "Explain Hibernate caching.", "**Direct answer :**\nHibernate has two levels of caching: first-level cache (session-level, mandatory) and second-level cache (session-factory-level, optional). First-level cache stores entities in the session, ensuring uniqueness within a session. Second-level cache can be shared across sessions to reduce DB hits.\n\n**Why this is asked :**\nInterviewers ask this to test your knowledge of performance optimization in Hibernate.\n\n**Breaking it down :**\n- **First-level cache**: Associated with \`Session\`, enabled by default. Holds entities and queries. Cleared when session is closed. Helps with repeat reads within same session.\n- **Second-level cache**: Shared across sessions. Requires explicit configuration (e.g., using EhCache, Infinispan). Can cache entities, collections, and queries. Reduces DB load.\n- **Query cache**: Caches query results (depends on second-level cache).\n\n**How to structure your spoken answer :**\nDefine both caches. Explain their scopes and benefits. Mention that second-level cache needs configuration. Give an example: using \`@Cacheable\` and \`@Cache\` annotations. Discuss when to use caching.\n\n**Follow-up angle to anticipate :**\nBe ready to discuss cache strategies (read-only, read-write, transactional) and cache invalidation."],
  ["Advanced Java", "What is lazy loading in Hibernate and how does it work?", "lazy-loading-hibernate", "Explain lazy loading.", "**Direct answer :**\nLazy loading is a strategy where associated entities are not loaded from the database until they are accessed. It is implemented using proxies or collections. It improves performance by reducing initial data loading but can cause \`LazyInitializationException\` if accessed outside the session.\n\n**Why this is asked :**\nInterviewers ask this to check your understanding of performance optimization and potential pitfalls.\n\n**Breaking it down :**\n- Lazy loading is configured using \`fetch = FetchType.LAZY\` on relationships (default for \`@OneToMany\`, \`@ManyToMany\`).\n- Hibernate uses proxies for single-ended relationships and persistent collections for multi-valued.\n- When you access a lazy property, Hibernate initializes it with a DB query (if session is open).\n- If you access it after the session is closed, you get \`LazyInitializationException\`. Solutions: \`JOIN FETCH\` in query, \`Hibernate.initialize()\`, or open session in view pattern.\n\n**How to structure your spoken answer :**\nDefine lazy loading. Explain its purpose. Describe how it's implemented. Mention the exception and how to avoid. Give an example of a \`@OneToMany(fetch = LAZY)\`.\n\n**Follow-up angle to anticipate :**\nBe ready to discuss the difference between EAGER and LAZY, and when to use each."],
  ["Advanced Java", "What is the `N+1` problem in Hibernate and how do you solve it?", "n-plus-one-problem", "Explain N+1 problem.", "**Direct answer :**\nThe N+1 problem occurs when you fetch a list of entities, and then for each entity, you fetch its lazy associations, resulting in N extra queries. It can be solved by using \`JOIN FETCH\` in JPQL, \`@EntityGraph\`, or setting fetch mode to subselect.\n\n**Why this is asked :**\nInterviewers ask this to test your ability to identify and fix performance issues.\n\n**Breaking it down :**\n- If you have \`List<Parent> parents = session.createQuery(\"from Parent\").list();\` and then iterate and access \`parent.getChildren()\`, Hibernate fires a query for each parent's children (N queries).\n- Solutions:\n  - \`JOIN FETCH\`: \`from Parent p join fetch p.children\` – loads children in the same query.\n  - \`@EntityGraph\`: Define a graph to specify which associations to fetch.\n  - \`@BatchSize\`: Use \`@BatchSize(size=10)\` on the association to batch queries.\n  - Subselect fetch: \`@Fetch(FetchMode.SUBSELECT)\`.\n\n**How to structure your spoken answer :**\nDescribe the N+1 problem. Explain why it happens and its performance impact. List solutions with examples. Mention that \`JOIN FETCH\` is the most common.\n\n**Follow-up angle to anticipate :**\nBe ready to discuss the trade-offs of using \`JOIN FETCH\` (cartesian product) and when to use batch fetching."],
  ["Advanced Java", "What is the difference between `@NamedQuery` and `@Query` in Spring Data JPA?", "namedquery-vs-query", "Compare @NamedQuery and @Query.", "**Direct answer :**\n\`@NamedQuery\` is a JPA annotation defining a static query on the entity class, which is compiled at startup. \`@Query\` is a Spring Data JPA annotation on a repository method, which defines a query at the method level and can be JPQL or native SQL.\n\n**Why this is asked :**\nInterviewers ask this to test your knowledge of query definition in JPA.\n\n**Breaking it down :**\n- \`@NamedQuery\`: Defined on the entity class with a unique name. Used by \`EntityManager.createNamedQuery()\`. It's precompiled, so it can be more performant. Not specific to Spring.\n- \`@Query\`: Spring Data JPA annotation on a repository method. Can be JPQL or native SQL. Supports dynamic queries with SpEL. It's more flexible and easier to use.\n\n**How to structure your spoken answer :**\nDefine both. Explain that \`@NamedQuery\` is JPA standard, \`@Query\` is Spring Data. Mention that \`@Query\` is more convenient for repository methods and can be defined directly in the interface. Give an example of each.\n\n**Follow-up angle to anticipate :**\nBe ready to discuss the use of native queries and how to handle pagination with \`@Query\`."],
  ["Advanced Java", "What is the difference between `save()` and `saveAndFlush()` in Spring Data JPA?", "save-vs-saveandflush", "Compare save() and saveAndFlush().", "**Direct answer :**\n\`save()\` persists an entity and returns the persisted instance; it may flush later. \`saveAndFlush()\` persists and immediately flushes the changes to the database, ensuring the entity is saved synchronously.\n\n**Why this is asked :**\nInterviewers ask this to test your understanding of flush behavior in JPA.\n\n**Breaking it down :**\n- \`save()\`: Part of \`CrudRepository\`. It persists the entity and returns it. The flush may happen at transaction commit or before query execution depending on flush mode.\n- \`saveAndFlush()\`: Spring Data JPA's \`JpaRepository\` method. It calls \`save()\` and then \`flush()\`, guaranteeing that the entity is written to the DB immediately.\n\n**How to structure your spoken answer :**\nDefine both. Explain that \`saveAndFlush\` is useful when you need the ID generated immediately or want to catch database constraint violations early.\n\n**Follow-up angle to anticipate :**\nBe ready to discuss the difference between \`flush\` and \`commit\`."],
  ["Advanced Java", "What is the `PersistenceContext` in JPA?", "persistencecontext", "Explain PersistenceContext.", "**Direct answer :**\n\`PersistenceContext\` is the environment that manages entities in JPA. It is a set of managed entity instances. In Hibernate, it's analogous to the \`Session\`. It has a lifecycle and can be either transaction-scoped or extended.\n\n**Why this is asked :**\nInterviewers ask this to test your understanding of JPA's entity management.\n\n**Breaking it down :**\n- \`PersistenceContext\` holds managed entities and tracks changes. It ensures that within a context, each entity has a unique identity.\n- In container-managed (Java EE), it's often transaction-scoped (begins and ends with transaction). In Spring, it's typically bound to the transaction.\n- \`EntityManager\` is the API to interact with the persistence context.\n\n**How to structure your spoken answer :**\nDefine PersistenceContext as the set of managed entities. Explain its role in change tracking and identity. Mention that it's associated with an \`EntityManager\`. Contrast with second-level cache.\n\n**Follow-up angle to anticipate :**\nBe ready to discuss the differences between transaction-scoped and extended persistence contexts."],
  ["Advanced Java", "What is the `@Version` annotation in JPA?", "version-annotation-jpa", "Explain @Version.", "**Direct answer :**\n\`@Version\` is used for optimistic locking. It marks a field (usually numeric or timestamp) that is incremented each time an entity is updated. When updating, JPA checks if the version in the DB matches the version in the entity; if not, an \`OptimisticLockException\` is thrown.\n\n**Why this is asked :**\nInterviewers ask this to test your understanding of concurrency control in JPA.\n\n**Breaking it down :**\n- Optimistic locking allows concurrent updates without locking, but detects conflicts at commit.\n- \`@Version\` on a numeric field (int, long) or timestamp. The value is automatically incremented or updated.\n- When an entity is updated, the version in the entity must match the database version; otherwise, an exception is thrown.\n\n**How to structure your spoken answer :**\nDefine optimistic locking. Explain \`@Version\`. Give an example: adding a \`@Version\` field to an entity. Mention that it prevents lost updates. Describe what happens on conflict and how to handle it.\n\n**Follow-up angle to anticipate :**\nBe ready to discuss pessimistic locking and the differences."],
  ["Advanced Java", "What is the difference between `@Entity` and `@MappedSuperclass`?", "entity-vs-mappedsuperclass", "Compare @Entity and @MappedSuperclass.", "**Direct answer :**\n\`@Entity\` defines a persistent entity that maps to a database table. \`@MappedSuperclass\` defines a superclass that provides common fields/mappings but does not have a corresponding table; it's used for inheritance where the subclass is the entity.\n\n**Why this is asked :**\nInterviewers ask this to test your knowledge of inheritance mapping.\n\n**Breaking it down :**\n- \`@Entity\`: The class is a full entity, with its own table.\n- \`@MappedSuperclass\`: The class is not an entity; it's a base class that defines mapping information that will be applied to its subclasses. The subclass must be an \`@Entity\` and will have its own table with the mapped fields.\n- You cannot query a \`@MappedSuperclass\` directly.\n\n**How to structure your spoken answer :**\nDefine both. Explain that \`@MappedSuperclass\` is for sharing common attributes (id, created date) across entities. Give an example: a BaseEntity with id and version. Mention that it's different from \`@Inheritance\` strategies.\n\n**Follow-up angle to anticipate :**\nBe ready to discuss the three inheritance strategies: SINGLE_TABLE, TABLE_PER_CLASS, JOINED."],
  ["Advanced Java", "What are the different inheritance mapping strategies in JPA?", "jpa-inheritance-strategies", "Explain JPA inheritance strategies.", "**Direct answer :**\nJPA supports three inheritance strategies: \`SINGLE_TABLE\` (all classes in one table with discriminator), \`TABLE_PER_CLASS\` (each class has its own table, no polymorphism in queries), and \`JOINED\` (subclass tables join with superclass table).\n\n**Why this is asked :**\nInterviewers ask this to test your ability to design database schemas for inheritance.\n\n**Breaking it down :**\n- **SINGLE_TABLE**: All entities in hierarchy are stored in one table. Uses a discriminator column to differentiate types. Good performance (no joins), but columns for subclass attributes must be nullable. Usually the default.\n- **TABLE_PER_CLASS**: Each concrete class has its own table with all attributes (including inherited). No polymorphic queries across hierarchy (union needed). Less common.\n- **JOINED**: Superclass table holds common attributes, subclass tables hold specific attributes, joined by primary key. Normalized, but requires joins for polymorphic queries.\n\n**How to structure your spoken answer :**\nList the three strategies. Explain each with pros/cons. Mention that SINGLE_TABLE is often used for simplicity. Give an example: \`@Inheritance(strategy=InheritanceType.SINGLE_TABLE)\`.\n\n**Follow-up angle to anticipate :**\nBe ready to discuss the discriminator column and how to choose the right strategy."],

  // ==================== WEB SERVICES (10) ====================
  ["Advanced Java", "What is a RESTful web service and what are its principles?", "restful-web-service", "Explain RESTful principles.", "**Direct answer :**\nREST (Representational State Transfer) is an architectural style for designing networked applications. Its principles include statelessness, client-server separation, cacheability, uniform interface (HTTP methods), and resource-based URIs.\n\n**Why this is asked :**\nInterviewers ask this to test your understanding of REST API design.\n\n**Breaking it down :**\n- **Resource**: identified by a URI.\n- **HTTP methods**: GET, POST, PUT, DELETE, PATCH.\n- **Stateless**: each request contains all needed info; no client session on server.\n- **Representations**: JSON, XML, etc.\n- **HATEOAS**: hypermedia as the engine of application state (optional).\n\n**How to structure your spoken answer :**\nDefine REST. List its key constraints. Explain how they lead to scalable, decoupled services. Give an example of a REST API for a user resource.\n\n**Follow-up angle to anticipate :**\nBe ready to discuss the difference between REST and SOAP, and HTTP status codes."],
  ["Advanced Java", "What is the difference between REST and SOAP?", "rest-vs-soap", "Compare REST and SOAP.", "**Direct answer :**\nREST is an architectural style using HTTP and resources; SOAP is a protocol with XML messaging, WSDL, and WS-* standards. REST is lightweight and stateless, while SOAP is heavier and supports more security and transactions.\n\n**Why this is asked :**\nInterviewers ask this to test your understanding of web service styles and when to use each.\n\n**Breaking it down :**\n- **REST**: Uses HTTP methods, stateless, resource-oriented, JSON/XML, simpler, better for public APIs.\n- **SOAP**: Uses XML, SOAP envelope, WSDL for contract, supports WS-Security, WS-AtomicTransaction, more complex, often used in enterprise.\n\n**How to structure your spoken answer :**\nDefine both. Contrast based on protocol, message format, state, security, and use cases. Mention that REST is more common for modern APIs, SOAP for legacy enterprise.\n\n**Follow-up angle to anticipate :**\nBe ready to discuss when to choose one over the other."],
  ["Advanced Java", "What is JAX-RS and how do you use it?", "jax-rs", "Explain JAX-RS.", "**Direct answer :**\nJAX-RS (Java API for RESTful Web Services) is a Java specification for building RESTful services using annotations like \`@Path\`, \`@GET\`, \`@POST\`, \`@Produces\`, \`@Consumes\`. Implementations include Jersey and RESTEasy.\n\n**Why this is asked :**\nInterviewers ask this to check your knowledge of Java's standard REST API.\n\n**Breaking it down :**\n- \`@Path\`: defines the URI template.\n- \`@GET\`, \`@POST\`, etc.: maps HTTP methods.\n- \`@Produces\`: specifies response media type (e.g., \`MediaType.APPLICATION_JSON\`).\n- \`@Consumes\`: specifies request media type.\n- \`@PathParam\`, \`@QueryParam\`, \`@FormParam\` for parameter extraction.\n- \`Response\` for building custom responses.\n\n**How to structure your spoken answer :**\nDefine JAX-RS. Explain the core annotations. Give a simple example of a REST endpoint. Mention popular implementations (Jersey). Note that Spring MVC also provides REST support, but JAX-RS is the standard.\n\n**Follow-up angle to anticipate :**\nBe ready to discuss the differences between JAX-RS and Spring MVC for REST."],
  ["Advanced Java", "What is JAX-WS and how does it differ from JAX-RS?", "jax-ws-vs-jax-rs", "Compare JAX-WS and JAX-RS.", "**Direct answer :**\nJAX-WS is a Java API for SOAP web services, using WSDL and XML. JAX-RS is for RESTful services. JAX-WS is more contract-driven and supports WS-*, while JAX-RS is simpler and uses HTTP.\n\n**Why this is asked :**\nInterviewers ask this to test your understanding of Java web services.\n\n**Breaking it down :**\n- **JAX-WS**: SOAP, XML, WSDL, more complex, supports reliable messaging and security.\n- **JAX-RS**: REST, HTTP, JSON/XML, simpler.\n\n**How to structure your spoken answer :**\nDefine both. Contrast based on protocol, message format, and complexity. Mention use cases: JAX-WS for enterprise integrations, JAX-RS for public APIs.\n\n**Follow-up angle to anticipate :**\nBe ready to discuss the role of WSDL and how to generate clients."],
  ["Advanced Java", "What is a WSDL?", "wsdl", "Explain WSDL.", "**Direct answer :**\nWSDL (Web Services Description Language) is an XML-based language for describing SOAP web services. It defines the endpoint, operations, messages, and bindings. Used to generate client stubs.\n\n**Why this is asked :**\nInterviewers ask this to check your knowledge of SOAP service definition.\n\n**Breaking it down :**\nWSDL contains: types (data types), message (parameters), portType (operations), binding (protocol), and service (endpoint address). It is used in SOAP-based services, allowing clients to understand how to interact.\n\n**How to structure your spoken answer :**\nDefine WSDL. Explain its purpose and components. Mention that it is part of the SOAP stack and can be used with tools like \`wsimport\` to generate Java classes.\n\n**Follow-up angle to anticipate :**\nBe ready to discuss the differences between WSDL 1.1 and 2.0."],
  ["Advanced Java", "How do you create a REST API with Spring Boot?", "spring-boot-rest-api", "Explain creating REST API with Spring Boot.", "**Direct answer :**\nWith Spring Boot, you create a REST API by adding \`spring-boot-starter-web\`, defining a \`@RestController\` with \`@GetMapping\` etc., and using \`@RequestBody\`, \`@PathVariable\`, \`@RequestParam\`. The API is exposed on an embedded server.\n\n**Why this is asked :**\nInterviewers ask this to test your practical skills in building REST services.\n\n**Breaking it down :**\n- Add dependency: \`spring-boot-starter-web\`.\n- Create a \`@RestController\` class with request mapping methods.\n- Use \`@GetMapping\`, \`@PostMapping\`, etc.\n- Use \`@Autowired\` for services.\n- Return objects (will be serialized to JSON by default).\n- Run the Spring Boot application.\n\n**How to structure your spoken answer :**\nDescribe the steps. Give a simple example: \`@RestController @RequestMapping(\"/api/users\")\` with \`@GetMapping(\"/{id}\")\`. Mention that Spring Boot auto-configures Jackson for JSON serialization.\n\n**Follow-up angle to anticipate :**\nBe ready to discuss error handling, validation, and documentation (Swagger)."],
  ["Advanced Java", "What is the `@ExceptionHandler` and `@ControllerAdvice`?", "exceptionhandler-controlleradvice", "Explain exception handling in Spring.", "**Direct answer :**\n\`@ExceptionHandler\` handles exceptions thrown by a specific controller. \`@ControllerAdvice\` globalizes exception handling across all controllers, providing centralized error handling.\n\n**Why this is asked :**\nInterviewers ask this to test your ability to implement robust error handling.\n\n**Breaking it down :**\n- \`@ExceptionHandler\`: Defined within a controller to handle specific exceptions from that controller.\n- \`@ControllerAdvice\`: A class annotated with \`@ControllerAdvice\` can contain \`@ExceptionHandler\`, \`@InitBinder\`, and \`@ModelAttribute\` methods that apply globally.\n- You can return \`ResponseEntity\` with custom error structure.\n\n**How to structure your spoken answer :**\nDefine both. Explain that \`@ControllerAdvice\` is used for global exception handling. Give an example of handling \`DataIntegrityViolationException\` and returning a user-friendly message. Mention that you can also use \`@ResponseStatus\`.\n\n**Follow-up angle to anticipate :**\nBe ready to discuss how to structure error responses (e.g., with timestamp, message, path)."],
  ["Advanced Java", "What is the difference between `@ResponseBody` and `@ResponseEntity`?", "responsebody-vs-responseentity", "Compare @ResponseBody and @ResponseEntity.", "**Direct answer :**\n\`@ResponseBody\` indicates that the return value of a method should be written directly to the HTTP response body. \`@ResponseEntity\` represents the entire HTTP response, including status, headers, and body, offering more control.\n\n**Why this is asked :**\nInterviewers ask this to test your knowledge of response customization.\n\n**Breaking it down :**\n- \`@ResponseBody\`: Used on a method to serialize the return object to the response body (often JSON).\n- \`@ResponseEntity<T>\`: A class that allows you to set status code, headers, and body explicitly. Commonly used to return different status codes (e.g., 201 Created, 404 Not Found).\n\n**How to structure your spoken answer :**\nDefine both. Explain that \`@ResponseBody\` is simpler, while \`@ResponseEntity\` provides full control. Give an example: returning \`ResponseEntity.created(location).body(obj)\` for a POST.\n\n**Follow-up angle to anticipate :**\nBe ready to discuss the use of \`@ResponseStatus\` as an alternative."],
  ["Advanced Java", "What is the `RestTemplate` and how is it used?", "resttemplate", "Explain RestTemplate.", "**Direct answer :**\n\`RestTemplate\` is a synchronous client for making HTTP requests in Spring. It provides methods like \`getForObject()\`, \`postForObject()\`, \`exchange()\` to interact with REST APIs. It's being replaced by \`WebClient\` for reactive.\n\n**Why this is asked :**\nInterviewers ask this to test your ability to consume REST services.\n\n**Breaking it down :**\n- \`RestTemplate\` is thread-safe after configuration.\n- You can set message converters, error handlers, interceptors.\n- It simplifies common operations like GET, POST, PUT, DELETE.\n- For asynchronous or reactive, use \`WebClient\`.\n\n**How to structure your spoken answer :**\nDefine RestTemplate. Explain its common methods. Give an example: \`restTemplate.getForObject(url, User.class)\`. Mention that in Spring Boot, you can create a \`RestTemplate\` bean. Note that it's not recommended for new projects; use \`WebClient\`.\n\n**Follow-up angle to anticipate :**\nBe ready to discuss the advantages of \`WebClient\` over \`RestTemplate\`."],
  ["Advanced Java", "What is `WebClient` and how does it differ from `RestTemplate`?", "webclient-vs-resttemplate", "Compare WebClient and RestTemplate.", "**Direct answer :**\n\`WebClient\` is a non-blocking, reactive client for HTTP requests introduced in Spring 5. It supports asynchronous and streaming, while \`RestTemplate\` is synchronous and blocking. \`WebClient\` is recommended for new applications.\n\n**Why this is asked :**\nInterviewers ask this to test your knowledge of modern HTTP clients.\n\n**Breaking it down :**\n- \`WebClient\`: Part of Spring WebFlux, uses reactive streams. Non-blocking, supports backpressure. Can be used in both synchronous and asynchronous style.\n- \`RestTemplate\`: Blocking, based on Java's \`HttpURLConnection\` or Apache HttpClient. Simpler but less performant for high-concurrency.\n\n**How to structure your spoken answer :**\nDefine both. Contrast on blocking vs non-blocking. Mention that \`WebClient\` is the future, and \`RestTemplate\` is deprecated. Give an example: \`webClient.get().uri(url).retrieve().bodyToMono(User.class)\`.\n\n**Follow-up angle to anticipate :**\nBe ready to discuss how to use WebClient with error handling and timeouts."],

  // ==================== MICROSERVICES (10) ====================
  ["Advanced Java", "What are microservices and what are their benefits?", "microservices-overview", "Define microservices.", "**Direct answer :**\nMicroservices are a software architecture style where an application is composed of small, independently deployable services that communicate via lightweight protocols (HTTP/REST, messaging). Benefits: scalability, flexibility, technology heterogeneity, and faster deployment.\n\n**Why this is asked :**\nInterviewers ask this to test your understanding of modern distributed architecture.\n\n**Breaking it down :**\n- Each microservice focuses on a specific business capability.\n- They are loosely coupled, independently deployable, and scalable.\n- They own their own data and can use different tech stacks.\n- Drawbacks: complexity, network latency, distributed transactions, and monitoring challenges.\n\n**How to structure your spoken answer :**\nDefine microservices. List benefits. Contrast with monolith. Mention challenges. Conclude that it's suitable for large, complex applications.\n\n**Follow-up angle to anticipate :**\nBe ready to discuss the difference between microservices and SOA."],
  ["Advanced Java", "What is service discovery and how does Eureka work?", "service-discovery-eureka", "Explain Eureka.", "**Direct answer :**\nService discovery is a pattern where services register themselves with a registry, and clients discover them. Eureka is a Netflix service registry used in Spring Cloud. Services register with Eureka server, and clients use Eureka client to locate services.\n\n**Why this is asked :**\nInterviewers ask this to test your knowledge of dynamic service location.\n\n**Breaking it down :**\n- **Eureka Server**: registry that holds service instances. Each microservice registers with it.\n- **Eureka Client**: embedded in each service to register, renew lease, and query for other services.\n- Services periodically send heartbeats; if not, they are removed.\n- Clients use load balancing (Ribbon) to choose instance.\n\n**How to structure your spoken answer :**\nDefine service discovery. Explain Eureka's role in Spring Cloud. Describe registration and discovery process. Mention that it's used with Spring Cloud Netflix.\n\n**Follow-up angle to anticipate :**\nBe ready to discuss alternatives like Consul, Zookeeper, and Kubernetes."],
  ["Advanced Java", "What is an API Gateway and what are its responsibilities?", "api-gateway", "Explain API Gateway.", "**Direct answer :**\nAn API Gateway is a single entry point for all client requests, providing routing, aggregation, authentication, rate limiting, and logging. It shields internal microservices from clients and handles cross-cutting concerns.\n\n**Why this is asked :**\nInterviewers ask this to test your understanding of microservices infrastructure.\n\n**Breaking it down :**\n- **Responsibilities**: request routing, authentication/authorization, rate limiting, caching, logging, monitoring, and sometimes response aggregation.\n- **Spring Cloud Gateway** is a popular implementation. It uses routes with predicates and filters.\n\n**How to structure your spoken answer :**\nDefine API Gateway. List its functions. Explain that it acts as a facade. Mention Spring Cloud Gateway and its features. Give an example of routing \`/api/users/**\` to the user service.\n\n**Follow-up angle to anticipate :**\nBe ready to discuss the difference between API Gateway and load balancer."],
  ["Advanced Java", "What is the Spring Cloud Config Server?", "config-server", "Explain Spring Cloud Config.", "**Direct answer :**\nSpring Cloud Config Server provides centralized external configuration for microservices. It serves configuration properties from a Git repository, allowing different environments (dev, prod) to have different properties. Clients can refresh configurations without restart.\n\n**Why this is asked :**\nInterviewers ask this to test your knowledge of configuration management in distributed systems.\n\n**Breaking it down :**\n- Config Server exposes endpoints like \`/{application}/{profile}/{label}\` to fetch properties.\n- Clients (microservices) use \`spring-cloud-starter-config\` to fetch config at startup.\n- Supports property overrides and encryption.\n- Can be refreshed with \`@RefreshScope\` and \`/actuator/refresh\`.\n\n**How to structure your spoken answer :**\nDefine Config Server. Explain its purpose: centralized configuration. Describe how it works with Git. Mention its benefits: environment-specific config, dynamic updates. Give an example of using it.\n\n**Follow-up angle to anticipate :**\nBe ready to discuss how to secure Config Server and the use of profiles."],
  ["Advanced Java", "What is distributed tracing and how does Sleuth work?", "distributed-tracing-sleuth", "Explain Sleuth.", "**Direct answer :**\nDistributed tracing tracks requests as they propagate through multiple microservices. Spring Cloud Sleuth adds trace and span IDs to logs, enabling correlation. It integrates with Zipkin for visualization.\n\n**Why this is asked :**\nInterviewers ask this to test your knowledge of monitoring and debugging microservices.\n\n**Breaking it down :**\n- Sleuth adds \`traceId\` and \`spanId\` to MDC (Mapped Diagnostic Context) for logging.\n- A trace represents the entire request; spans represent individual service calls.\n- Zipkin collects and displays traces, showing latency and dependencies.\n\n**How to structure your spoken answer :**\nDefine distributed tracing. Explain Sleuth's role: adding identifiers to logs. Mention Zipkin for visualization. Describe a typical flow: request enters gateway, trace created, spans added, logs show IDs, Zipkin aggregates.\n\n**Follow-up angle to anticipate :**\nBe ready to discuss how to use Sleuth with logs and monitoring tools."],
  ["Advanced Java", "What is the `@EnableDiscoveryClient` annotation?", "enablediscoveryclient", "Explain @EnableDiscoveryClient.", "**Direct answer :**\n\`@EnableDiscoveryClient\` is a Spring Cloud annotation that enables service registration and discovery for a Spring Boot application. It makes the application a client of a service registry (Eureka, Consul, etc.).\n\n**Why this is asked :**\nInterviewers ask this to test your understanding of service registration.\n\n**Breaking it down :**\n- This annotation triggers auto-configuration for discovery clients.\n- It integrates with the Spring Cloud \`DiscoveryClient\` interface.\n- The application will register itself with the registry and can query for other services.\n\n**How to structure your spoken answer :**\nDefine the annotation. Explain that it's used on the main class. Mention that it requires a registry dependency (e.g., Eureka). Give an example.\n\n**Follow-up angle to anticipate :**\nBe ready to discuss the difference between \`@EnableDiscoveryClient\` and \`@EnableEurekaClient\`."],
  ["Advanced Java", "What is the difference between `@LoadBalanced` and `@EnableDiscoveryClient`?", "loadbalanced-vs-discovery", "Compare annotations.", "**Direct answer :**\n\`@LoadBalanced\` is used on a \`RestTemplate\` bean to enable client-side load balancing. \`@EnableDiscoveryClient\` enables service discovery. They often work together: the \`RestTemplate\` will use the service discovery client to resolve service names to actual instances and load balance.\n\n**Why this is asked :**\nInterviewers ask this to test your understanding of client-side load balancing.\n\n**Breaking it down :**\n- \`@LoadBalanced\`: Marks a \`RestTemplate\` to use a \`LoadBalancerInterceptor\` that replaces service names with actual host:port using a load balancer (e.g., Ribbon).\n- \`@EnableDiscoveryClient\`: Enables discovery client, allowing the application to interact with the registry.\n\n**How to structure your spoken answer :**\nDefine both. Explain that they are complementary: \`@EnableDiscoveryClient\` for registry interaction, \`@LoadBalanced\` for load balancing \`RestTemplate\` calls. Give an example: \`@Bean @LoadBalanced RestTemplate\` to call \`http://user-service/users\`.\n\n**Follow-up angle to anticipate :**\nBe ready to discuss the use of Spring Cloud LoadBalancer (replacing Ribbon)."],
  ["Advanced Java", "What is the Circuit Breaker pattern and how is it used in microservices?", "circuit-breaker-microservices", "Explain circuit breaker in microservices.", "**Direct answer :**\nCircuit breaker is a pattern that prevents cascading failures by stopping requests to a failing service. In microservices, it's used to handle service failures gracefully, providing fallbacks and preventing resource exhaustion.\n\n**Why this is asked :**\nInterviewers ask this to test your knowledge of resilience in microservices.\n\n**Breaking it down :**\n- As described earlier.\n- In microservices, circuit breakers protect against downstream service outages.\n- They are often combined with retries, timeouts, and bulkheads.\n- Implementations: Resilience4j, Hystrix.\n\n**How to structure your spoken answer :**\nDefine the pattern. Explain its importance in distributed systems. Describe how it's implemented (Resilience4j). Mention that it's used with Spring Cloud.\n\n**Follow-up angle to anticipate :**\nBe ready to discuss other resilience patterns (retry, timeout, rate limiter)."],
  ["Advanced Java", "What is the Spring Cloud Bus?", "spring-cloud-bus", "Explain Spring Cloud Bus.", "**Direct answer :**\nSpring Cloud Bus links nodes of a distributed system with a lightweight message broker. It is used to broadcast configuration changes (e.g., refresh) to multiple services without restarting.\n\n**Why this is asked :**\nInterviewers ask this to test your knowledge of dynamic configuration propagation.\n\n**Breaking it down :**\n- Uses a message broker (RabbitMQ, Kafka) to propagate events.\n- Common use: \`@RefreshScope\` beans can be refreshed by sending a \`refresh\` event to the bus.\n- All services receive the event and refresh their configuration.\n\n**How to structure your spoken answer :**\nDefine Spring Cloud Bus. Explain its purpose: to propagate state changes. Give an example: updating config in Git, sending \`/bus-refresh\` to one service, all services receive config update. Mention that it reduces manual intervention.\n\n**Follow-up angle to anticipate :**\nBe ready to discuss alternatives like using Kubernetes ConfigMaps."],
  ["Advanced Java", "What is the `@CircuitBreaker` annotation in Resilience4j?", "resilience4j-circuitbreaker", "Explain Resilience4j @CircuitBreaker.", "**Direct answer :**\n\`@CircuitBreaker\` is a Resilience4j annotation used with Spring Boot to apply circuit breaker logic to a method. It specifies fallback methods and configuration like failure rate, sliding window, etc.\n\n**Why this is asked :**\nInterviewers ask this to test your knowledge of Resilience4j.\n\n**Breaking it down :**\n- Add \`spring-boot-starter-aop\` and \`resilience4j-spring-boot2\`.\n- Use \`@CircuitBreaker(name = \"service\", fallbackMethod = \"fallback\")\`.\n- Define a fallback method with same signature and an optional exception parameter.\n- Configuration in \`application.yml\` (e.g., slidingWindowSize, failureRateThreshold).\n\n**How to structure your spoken answer :**\nDefine the annotation. Explain its attributes. Give an example of its usage. Mention that it integrates with Spring Boot's auto-configuration.\n\n**Follow-up angle to anticipate :**\nBe ready to discuss other Resilience4j annotations: \`@Retry\`, \`@RateLimiter\`, \`@Bulkhead\`."],

  // ==================== CONCURRENCY (10) ====================
  ["Advanced Java", "What is the difference between a process and a thread?", "process-vs-thread", "Compare process and thread.", "**Direct answer :**\nA process is an independent program in execution with its own memory space. A thread is a lightweight unit of execution within a process; threads share the process's memory and resources.\n\n**Why this is asked :**\nInterviewers ask this to test your foundational knowledge of concurrency.\n\n**Breaking it down :**\n- **Process**: Has own address space, file descriptors, and system resources. Inter-process communication is expensive.\n- **Thread**: Shares heap, code, and data with other threads in the same process. Communication is cheaper but requires synchronization.\n\n**How to structure your spoken answer :**\nDefine both. Contrast by memory, overhead, and communication. Mention that threads are used for parallel tasks within an application.\n\n**Follow-up angle to anticipate :**\nBe ready to discuss the lifecycle of threads and how to create them."],
  ["Advanced Java", "What are the ways to create a thread in Java?", "create-thread-java", "List ways to create threads.", "**Direct answer :**\nTwo ways: extending \`Thread\` class and overriding \`run()\`, or implementing \`Runnable\` interface and passing to \`Thread\`. The \`Runnable\` approach is preferred because it allows extending another class.\n\n**Why this is asked :**\nInterviewers ask this to test your basic thread creation knowledge.\n\n**Breaking it down :**\n- **Extend Thread**: \`class MyThread extends Thread { public void run() {...} }\` then \`new MyThread().start()\`.\n- **Implement Runnable**: \`class MyRunnable implements Runnable { public void run() {...} }\` then \`new Thread(new MyRunnable()).start()\`.\n- Also: using \`Callable\` and \`FutureTask\` for returning results.\n- With \`ExecutorService\` for thread pools.\n\n**How to structure your spoken answer :**\nList the two main ways. Explain the pros and cons. Mention that implementing \`Runnable\` is more flexible. Give examples.\n\n**Follow-up angle to anticipate :**\nBe ready to discuss the \`Callable\` interface and \`ExecutorService\`."],
  ["Advanced Java", "What is the difference between `synchronized` method and block?", "synchronized-method-vs-block", "Compare synchronized methods and blocks.", "**Direct answer :**\n\`synchronized\` method locks the entire method on the object instance (or class for static). \`synchronized\` block allows locking on a specific object and a specific section, providing more granular control.\n\n**Why this is asked :**\nInterviewers ask this to test your understanding of synchronization granularity.\n\n**Breaking it down :**\n- \`synchronized void method()\`: locks the whole method on \`this\` (or class).\n- \`synchronized(lockObject) { ... }\`: locks only the block on \`lockObject\`, allowing other code in the same method to run concurrently if not needing the lock.\n- Block is more efficient and flexible.\n\n**How to structure your spoken answer :**\nDefine both. Explain that block is more fine-grained. Give an example where you use a block to sync only critical section. Mention that method-level synchronization is simpler.\n\n**Follow-up angle to anticipate :**\nBe ready to discuss \`ReentrantLock\` as an alternative."],
  ["Advanced Java", "What is the `volatile` keyword in Java?", "volatile-keyword", "Explain volatile.", "**Direct answer :**\n\`volatile\` is a keyword that ensures visibility of changes to a variable across threads. It prevents caching of the variable locally and guarantees that reads/writes are directly from/to main memory.\n\n**Why this is asked :**\nInterviewers ask this to test your understanding of thread-safety and visibility.\n\n**Breaking it down :**\n- \`volatile\` does not provide atomicity (use \`AtomicXXX\` for that).\n- It ensures that a write to a volatile variable is immediately visible to other threads.\n- It also prevents certain compiler reorderings.\n- Used for flags, status variables.\n\n**How to structure your spoken answer :**\nDefine volatile. Explain its effect on visibility. Contrast with \`synchronized\` (which provides both visibility and atomicity). Give an example: a boolean flag to stop a thread.\n\n**Follow-up angle to anticipate :**\nBe ready to discuss the differences between volatile and synchronized, and \`Atomic\` classes."],
  ["Advanced Java", "What is the difference between `wait()`, `notify()`, and `notifyAll()`?", "wait-notify", "Explain wait/notify.", "**Direct answer :**\n\`wait()\` causes the current thread to wait until another thread calls \`notify()\` or \`notifyAll()\` on the same object. \`notify()\` wakes up one waiting thread, \`notifyAll()\` wakes all. They must be called from a synchronized context.\n\n**Why this is asked :**\nInterviewers ask this to test your understanding of inter-thread communication.\n\n**Breaking it down :**\n- \`wait()\`: releases the lock and waits. It can be called with timeout.\n- \`notify()\`: wakes a single thread waiting on the same object's monitor (arbitrary).\n- \`notifyAll()\`: wakes all waiting threads.\n- They are methods of \`Object\`. Must be called from \`synchronized\` block/method.\n\n**How to structure your spoken answer :**\nDefine each. Explain the need for synchronization. Give an example of producer-consumer. Mention that \`notifyAll\` is safer to avoid missed signals.\n\n**Follow-up angle to anticipate :**\nBe ready to discuss \`Condition\` from \`java.util.concurrent\` as a more flexible alternative."],
  ["Advanced Java", "What is `ExecutorService` and why is it used?", "executorservice", "Explain ExecutorService.", "**Direct answer :**\n\`ExecutorService\` is an interface that manages thread pools. It provides methods to submit tasks and manage their execution. It decouples task submission from execution, and reuses threads for efficiency.\n\n**Why this is asked :**\nInterviewers ask this to test your knowledge of high-level concurrency utilities.\n\n**Breaking it down :**\n- \`Executors\` factory provides static methods: \`newFixedThreadPool()\`, \`newCachedThreadPool()\`, \`newSingleThreadExecutor()\`, \`newScheduledThreadPool()\`.\n- \`submit(Callable/Runnable)\`, \`shutdown()\`, \`awaitTermination()\`.\n- It handles thread lifecycle, pooling, and queuing.\n\n**How to structure your spoken answer :**\nDefine ExecutorService. Explain its advantages: thread reuse, better resource management, simplifies thread management. Give an example: \`ExecutorService executor = Executors.newFixedThreadPool(10);\` then \`executor.submit(() -> {...})\`.\n\n**Follow-up angle to anticipate :**\nBe ready to discuss different types of thread pools and their use cases."],
  ["Advanced Java", "What is `CompletableFuture` and how does it improve upon `Future`?", "completablefuture", "Explain CompletableFuture.", "**Direct answer :**\n\`CompletableFuture\` is a class that implements \`Future\` and allows chaining asynchronous tasks using callbacks (\`thenApply\`, \`thenAccept\`, \`thenCompose\`). It provides non-blocking, promise-like composition and exception handling.\n\n**Why this is asked :**\nInterviewers ask this to test your knowledge of modern asynchronous programming.\n\n**Breaking it down :**\n- \`Future\` only provides \`get()\` (blocking) and \`cancel()\`. No composition.\n- \`CompletableFuture\` can be completed manually (by calling \`complete()\`). Supports functional composition: \`thenApply\` (transform), \`thenAccept\` (consume), \`thenCombine\` (combine), \`exceptionally\` for error handling.\n- It integrates with \`ExecutorService\` for custom pools.\n\n**How to structure your spoken answer :**\nDefine CompletableFuture. Contrast with Future. Give an example: \`CompletableFuture.supplyAsync(() -> fetchData()).thenApply(data -> process(data)).thenAccept(System.out::println)\`. Mention that it's used for reactive programming.\n\n**Follow-up angle to anticipate :**\nBe ready to discuss the differences between \`thenApply\` and \`thenCompose\`."],
  ["Advanced Java", "What is the difference between `Lock` and `synchronized`?", "lock-vs-synchronized", "Compare Lock and synchronized.", "**Direct answer :**\n\`Lock\` (from \`java.util.concurrent.locks\`) offers more flexible locking than \`synchronized\`. It provides \`tryLock()\`, \`lockInterruptibly()\`, and can be unlocked in a different scope. It also supports fairness policies.\n\n**Why this is asked :**\nInterviewers ask this to test your understanding of advanced concurrency control.\n\n**Breaking it down :**\n- \`synchronized\`: implicit locking, easy to use, but not flexible; cannot interrupt, no try-lock, no timeout.\n- \`Lock\`: explicit locking with \`lock()\` and \`unlock()\` (must be in finally block). Provides \`tryLock()\` (non-blocking), \`tryLock(long, TimeUnit)\`, and \`lockInterruptibly()\`. Can be fair.\n\n**How to structure your spoken answer :**\nDefine both. Contrast flexibility. Give use cases: \`ReentrantLock\` for advanced scenarios. Mention that \`synchronized\` is simpler and sufficient for most cases.\n\n**Follow-up angle to anticipate :**\nBe ready to discuss \`ReadWriteLock\` and \`StampedLock\`."],
  ["Advanced Java", "What are the `Atomic` classes in Java?", "atomic-classes", "Explain Atomic classes.", "**Direct answer :**\n\`Atomic\` classes (e.g., \`AtomicInteger\`, \`AtomicLong\`, \`AtomicReference\`) provide thread-safe operations on single variables without using locks. They use low-level CAS (Compare-And-Swap) instructions for performance.\n\n**Why this is asked :**\nInterviewers ask this to test your knowledge of lock-free concurrency.\n\n**Breaking it down :**\n- They support atomic operations like \`incrementAndGet()\`, \`compareAndSet()\`, \`getAndSet()\`.\n- They are faster than synchronization for simple operations.\n- They are not suitable for complex multi-variable invariants.\n\n**How to structure your spoken answer :**\nDefine atomic classes. Explain their purpose: lock-free concurrency. Give an example: \`AtomicInteger counter = new AtomicInteger(); counter.incrementAndGet();\`. Mention the CAS mechanism.\n\n**Follow-up angle to anticipate :**\nBe ready to discuss the \`compareAndSet\` method and its use."],
  ["Advanced Java", "What is the difference between `ConcurrentHashMap` and `Hashtable`?", "concurrenthashmap-vs-hashtable", "Compare ConcurrentHashMap and Hashtable.", "**Direct answer :**\n\`ConcurrentHashMap\` is a thread-safe map that provides higher concurrency by using lock striping (segmented locks). \`Hashtable\` is synchronized (single lock) and is legacy. \`ConcurrentHashMap\` allows concurrent reads and writes without full locking.\n\n**Why this is asked :**\nInterviewers ask this to test your knowledge of thread-safe collections.\n\n**Breaking it down :**\n- \`Hashtable\`: synchronized methods, only one thread can access at a time, poor performance.\n- \`ConcurrentHashMap\`: uses bucket-level locks (or CAS in Java 8+), supports high concurrency. It does not allow \`null\` keys or values.\n- \`ConcurrentHashMap\` is preferred in concurrent environments.\n\n**How to structure your spoken answer :**\nDefine both. Contrast by locking strategy and performance. Mention that \`ConcurrentHashMap\` also provides atomic operations like \`computeIfAbsent\`. Give a recommendation: use \`ConcurrentHashMap\`.\n\n**Follow-up angle to anticipate :**\nBe ready to discuss other concurrent collections: \`CopyOnWriteArrayList\`, \`ConcurrentLinkedQueue\`."],

  // ==================== JVM & PERFORMANCE (10) ====================
  ["Advanced Java", "What is the JVM and what is its architecture?", "jvm-architecture", "Explain JVM architecture.", "**Direct answer :**\nThe JVM (Java Virtual Machine) is the runtime environment for Java bytecode. Its architecture includes: Class Loader, Runtime Data Areas (Method Area, Heap, Stack, PC Registers, Native Method Stack), Execution Engine (Interpreter, JIT Compiler), and Garbage Collector.\n\n**Why this is asked :**\nInterviewers ask this to test your understanding of how Java runs.\n\n**Breaking it down :**\n- **Class Loader**: loads .class files.\n- **Runtime Data Areas**:\n  - Method Area: class metadata, static variables.\n  - Heap: all objects and arrays.\n  - Stack: per-thread, stores frames (local variables, operand stack).\n  - PC Registers: program counter per thread.\n  - Native Method Stack: for native methods.\n- **Execution Engine**: interprets bytecode; JIT compiles hot code to native for performance.\n- **Garbage Collector**: automatically reclaims memory.\n\n**How to structure your spoken answer :**\nDefine JVM. Describe each component briefly. Emphasize that heap is where objects live, and stack is for method execution. Mention that JIT improves performance.\n\n**Follow-up angle to anticipate :**\nBe ready to discuss classloading and memory areas in more detail."],
  ["Advanced Java", "What is the difference between heap and stack in Java?", "heap-vs-stack", "Compare heap and stack.", "**Direct answer :**\nHeap is the runtime data area where objects and arrays are allocated; it is shared by all threads. Stack is per-thread and stores method invocation frames (local variables, operands). Heap is managed by GC; stack is automatically freed.\n\n**Why this is asked :**\nInterviewers ask this to test your knowledge of memory management.\n\n**Breaking it down :**\n- **Heap**: larger, slower, garbage collected, shared, stores objects.\n- **Stack**: smaller, faster, LIFO, per-thread, stores primitive values and references to objects.\n- Stack overflow when too many nested calls; heap overflow when memory exhausted.\n\n**How to structure your spoken answer :**\nDefine both. Contrast based on size, lifetime, access speed, and what they store. Give examples: local variables on stack, objects on heap.\n\n**Follow-up angle to anticipate :**\nBe ready to discuss stack frames and how garbage collection works."],
  ["Advanced Java", "What are the different types of garbage collectors in Java?", "garbage-collectors", "List Java garbage collectors.", "**Direct answer :**\nJava has several garbage collectors: Serial, Parallel (Throughput), CMS (Concurrent Mark Sweep, deprecated), G1, and the latest ZGC and Shenandoah. Each has different trade-offs in throughput, latency, and footprint.\n\n**Why this is asked :**\nInterviewers ask this to test your knowledge of GC tuning and performance.\n\n**Breaking it down :**\n- **Serial**: single-threaded, for small applications.\n- **Parallel**: multi-threaded, focuses on throughput.\n- **CMS**: low pause, concurrent, deprecated in Java 9.\n- **G1**: default since Java 9, balanced, region-based, good for larger heaps.\n- **ZGC**: low latency, scalable to large heaps.\n- **Shenandoah**: low pause, concurrent.\n\n**How to structure your spoken answer :**\nList the collectors and their characteristics. Mention that G1 is the default. Explain the trade-offs. Give examples of when to use each.\n\n**Follow-up angle to anticipate :**\nBe ready to discuss how to choose a GC and tune GC parameters."],
  ["Advanced Java", "What is the `finalize()` method and why is it deprecated?", "finalize-method", "Explain finalize().", "**Direct answer :**\n\`finalize()\` was a method called by GC before reclaiming an object, used for cleanup. It's deprecated because it's unpredictable, can cause performance issues, and can be misused. Use \`try-with-resources\` or \`Cleaner\` instead.\n\n**Why this is asked :**\nInterviewers ask this to test your knowledge of resource cleanup and GC.\n\n**Breaking it down :**\n- \`finalize()\` is called at most once by GC.\n- It can resurrect objects; it's slow and not guaranteed to run.\n- Alternatives: \`try-with-resources\` for auto-closeable resources, \`Cleaner\` for native resources.\n\n**How to structure your spoken answer :**\nDefine finalize. Explain its problems: unpredictability, performance, and revival. Mention that it's deprecated. Provide alternatives.\n\n**Follow-up angle to anticipate :**\nBe ready to discuss \`Cleaner\` and \`PhantomReference\` for more reliable cleanup."],
  ["Advanced Java", "What is a memory leak in Java and how can you detect it?", "memory-leak-java", "Explain memory leak.", "**Direct answer :**\nA memory leak occurs when objects are no longer used but still referenced, preventing GC from reclaiming them. Causes: static collections, unclosed resources, listeners not removed, etc. Detection: using profilers (VisualVM, JProfiler) and heap dumps.\n\n**Why this is asked :**\nInterviewers ask this to test your ability to diagnose performance issues.\n\n**Breaking it down :**\n- Common causes: listeners added but never removed; caches with no eviction; static maps holding objects; thread locals not cleared.\n- Detection: use profiling tools to monitor heap, take heap dumps, analyze with MAT or JVisualVM.\n- Prevention: use weak references, ensure cleanup in finally blocks, use \`try-with-resources\`.\n\n**How to structure your spoken answer :**\nDefine memory leak. List causes. Explain detection tools and techniques. Mention how to prevent.\n\n**Follow-up angle to anticipate :**\nBe ready to discuss \`WeakHashMap\` and reference types."],
  ["Advanced Java", "What is the difference between `-Xms` and `-Xmx` JVM options?", "xms-vs-xmx", "Explain JVM heap options.", "**Direct answer :**\n\`-Xms\` sets the initial heap size; \`-Xmx\` sets the maximum heap size. For performance, set them equal to avoid resizing overhead.\n\n**Why this is asked :**\nInterviewers ask this to test your knowledge of JVM tuning.\n\n**Breaking it down :**\n- \`-Xms<size>\`: initial heap size.\n- \`-Xmx<size>\`: maximum heap size.\n- Other options: \`-Xss\` for stack size, \`-XX:MaxMetaspaceSize\`.\n\n**How to structure your spoken answer :**\nDefine both. Explain that setting them equal avoids GC resizing. Give typical values for different applications.\n\n**Follow-up angle to anticipate :**\nBe ready to discuss other JVM options like \`-XX:+UseG1GC\`."],
  ["Advanced Java", "What is the `OutOfMemoryError` and when does it occur?", "outofmemoryerror", "Explain OutOfMemoryError.", "**Direct answer :**\n\`OutOfMemoryError\` is thrown when the JVM cannot allocate an object due to insufficient memory. Causes: heap exhaustion, metaspace exhaustion, too many threads, or native memory exhaustion.\n\n**Why this is asked :**\nInterviewers ask this to test your understanding of JVM runtime errors.\n\n**Breaking it down :**\n- Common causes: memory leaks, too large objects, insufficient heap, infinite loops creating objects.\n- Types: \`Java heap space\`, \`Metaspace\`, \`Unable to create new native thread\`, \`GC overhead limit exceeded\`.\n- Resolution: increase heap, fix leaks, optimize code.\n\n**How to structure your spoken answer :**\nDefine OutOfMemoryError. List common causes and types. Mention how to diagnose (heap dump, profiler). Suggest fixes.\n\n**Follow-up angle to anticipate :**\nBe ready to discuss the difference between heap and metaspace OOM."],
  ["Advanced Java", "What is the `-XX:+PrintGCDetails` flag used for?", "printgcdetails", "Explain -XX:+PrintGCDetails.", "**Direct answer :**\n\`-XX:+PrintGCDetails\` is a JVM flag that logs garbage collection details, including pause times, space usage, and collection statistics. It's useful for GC tuning.\n\n**Why this is asked :**\nInterviewers ask this to test your ability to monitor and tune GC.\n\n**Breaking it down :**\n- It prints GC events to standard output or a log file.\n- Provides information about young/old generation sizes, duration, and throughput.\n- Modern alternative: \`-Xlog:gc*\` (unified logging).\n\n**How to structure your spoken answer :**\nExplain the flag. Describe what it logs. Mention that it's used for performance analysis. Give an example of output.\n\n**Follow-up angle to anticipate :**\nBe ready to discuss unified logging and how to analyze GC logs."],
  ["Advanced Java", "What is the difference between a `SoftReference` and a `WeakReference`?", "soft-vs-weak-reference", "Compare SoftReference and WeakReference.", "**Direct answer :**\n\`SoftReference\` is cleared by GC when memory is low; \`WeakReference\` is cleared more aggressively (as soon as no strong references). \`SoftReference\` is used for memory-sensitive caches; \`WeakReference\` for canonical mappings.\n\n**Why this is asked :**\nInterviewers ask this to test your knowledge of reference types.\n\n**Breaking it down :**\n- **SoftReference**: GC clears them before throwing OOM. Suitable for caches that can be rebuilt.\n- **WeakReference**: GC clears them whenever it runs; used for \`WeakHashMap\` and listener cleanup.\n- **PhantomReference**: used for post-mortem cleanup.\n\n**How to structure your spoken answer :**\nDefine both. Contrast based on GC behavior. Give use cases: soft for cache, weak for metadata. Mention \`ReferenceQueue\`.\n\n**Follow-up angle to anticipate :**\nBe ready to discuss \`PhantomReference\` and its use."],
  ["Advanced Java", "What is the purpose of the `ClassLoader` in Java?", "classloader", "Explain ClassLoader.", "**Direct answer :**\n\`ClassLoader\` is responsible for loading Java classes into the JVM. It follows a delegation hierarchy: Bootstrap (core classes), Extension, and Application (classpath). It can be custom to load classes from non-standard sources.\n\n**Why this is asked :**\nInterviewers ask this to test your understanding of class loading and dynamic code.\n\n**Breaking it down :**\n- **Bootstrap ClassLoader**: loads \`rt.jar\` (core JDK classes).\n- **Extension ClassLoader**: loads \`ext\` directory.\n- **Application ClassLoader**: loads classpath.\n- Delegation model ensures security (core classes not overridden).\n- Custom classloaders can load classes from network, encrypted files, etc.\n\n**How to structure your spoken answer :**\nDefine ClassLoader. Explain the hierarchy and delegation. Mention that it's part of JVM's architecture. Give an example: custom classloader for hot deployment.\n\n**Follow-up angle to anticipate :**\nBe ready to discuss class loading and \`ClassNotFoundException\`."],

  // ==================== DESIGN PATTERNS (15) ====================
  ["Advanced Java", "What is the Singleton pattern and how to implement it in Java?", "singleton-pattern", "Explain Singleton.", "**Direct answer :**\nSingleton ensures a class has only one instance and provides a global access point. Implementations: eager initialization, lazy (double-checked locking), static inner class, enum.\n\n**Why this is asked :**\nInterviewers ask this to test your knowledge of creational patterns and thread-safety.\n\n**Breaking it down :**\n- **Eager**: \`private static final Singleton instance = new Singleton();\`\n- **Lazy (double-checked)**: use \`volatile\` and \`synchronized\` block.\n- **Static inner class**: on-demand loading (bill pugh).\n- **Enum**: \`enum Singleton { INSTANCE; }\` – serialization safe.\n\n**How to structure your spoken answer :**\nDefine Singleton. List implementations. Explain thread-safety. Give the recommended approach: enum or static inner class.\n\n**Follow-up angle to anticipate :**\nBe ready to discuss the singleton vs static class and serialization issues."],
  ["Advanced Java", "What is the Factory pattern and its variations?", "factory-pattern", "Explain Factory pattern.", "**Direct answer :**\nFactory pattern provides an interface for creating objects without specifying concrete classes. Variations: Simple Factory, Factory Method, and Abstract Factory.\n\n**Why this is asked :**\nInterviewers ask this to test your understanding of creational patterns.\n\n**Breaking it down :**\n- **Simple Factory**: a class with a method that returns instances based on parameters.\n- **Factory Method**: defines an abstract method for creating objects, subclasses decide the concrete type.\n- **Abstract Factory**: provides an interface for creating families of related objects.\n\n**How to structure your spoken answer :**\nDefine the pattern and its purpose. Explain each variation with examples. Mention use cases like creating different database connections.\n\n**Follow-up angle to anticipate :**\nBe ready to discuss the difference between Factory and Abstract Factory."],
  ["Advanced Java", "What is the Builder pattern and when to use it?", "builder-pattern", "Explain Builder pattern.", "**Direct answer :**\nBuilder pattern constructs complex objects step by step. It separates the construction process from the representation. Used when an object has many optional parameters or a complex creation process.\n\n**Why this is asked :**\nInterviewers ask this to test your knowledge of object construction.\n\n**Breaking it down :**\n- Builder has a nested static class with methods to set each parameter.\n- The final \`build()\` method creates the object.\n- Example: \`User user = User.builder().name(\"John\").age(30).build();\` (with Lombok).\n- Advantages: readability, immutability, and validation.\n\n**How to structure your spoken answer :**\nDefine Builder. Explain its benefits. Give an example. Mention that it's used for objects with many attributes.\n\n**Follow-up angle to anticipate :**\nBe ready to discuss the difference between Builder and Factory."],
  ["Advanced Java", "What is the Prototype pattern?", "prototype-pattern", "Explain Prototype pattern.", "**Direct answer :**\nPrototype pattern creates new objects by cloning an existing instance (prototype) rather than using \`new\`. It's useful when object creation is expensive or when you need many similar objects.\n\n**Why this is asked :**\nInterviewers ask this to test your knowledge of alternative object creation.\n\n**Breaking it down :**\n- Implement \`Cloneable\` and override \`clone()\`.\n- Or use a copy constructor.\n- Used in scenarios like creating multiple configurations from a template.\n\n**How to structure your spoken answer :**\nDefine Prototype. Explain how it works (cloning). Give an example. Mention that shallow vs deep clone must be considered.\n\n**Follow-up angle to anticipate :**\nBe ready to discuss the \`Cloneable\` interface and its pitfalls."],
  ["Advanced Java", "What is the Adapter pattern?", "adapter-pattern", "Explain Adapter.", "**Direct answer :**\nAdapter pattern allows incompatible interfaces to work together. It acts as a bridge by wrapping an existing class with a new interface. Used for integrating legacy systems or third-party libraries.\n\n**Why this is asked :**\nInterviewers ask this to test your understanding of structural patterns.\n\n**Breaking it down :**\n- **Class Adapter**: uses inheritance (adapter extends target and adaptee).\n- **Object Adapter**: uses composition (adapter holds adaptee).\n- Example: \`List\` to \`Enumeration\` adapter.\n\n**How to structure your spoken answer :**\nDefine Adapter. Explain the two forms. Give an example: adapting a legacy API to a new interface.\n\n**Follow-up angle to anticipate :**\nBe ready to discuss the difference between Adapter and Proxy."],
  ["Advanced Java", "What is the Decorator pattern?", "decorator-pattern", "Explain Decorator.", "**Direct answer :**\nDecorator pattern adds behavior to an object dynamically without altering its structure. It uses composition to wrap the original object with additional functionality. Used for extending capabilities.\n\n**Why this is asked :**\nInterviewers ask this to test your ability to add functionality flexibly.\n\n**Breaking it down :**\n- Decorator implements the same interface as the component.\n- It wraps a component and adds extra behavior before/after delegating.\n- Example: Java I/O (e.g., \`BufferedReader\` wraps \`Reader\`).\n\n**How to structure your spoken answer :**\nDefine Decorator. Explain its structure. Give an example with Java I/O. Mention it's an alternative to subclassing.\n\n**Follow-up angle to anticipate :**\nBe ready to discuss the difference between Decorator and Proxy."],
  ["Advanced Java", "What is the Proxy pattern and its variants?", "proxy-pattern", "Explain Proxy.", "**Direct answer :**\nProxy pattern provides a surrogate or placeholder for another object to control access. Variants: virtual proxy (lazy loading), protection proxy (access control), remote proxy (local representation of remote object).\n\n**Why this is asked :**\nInterviewers ask this to test your understanding of access control and lazy loading.\n\n**Breaking it down :**\n- **Virtual**: delays creation of expensive object until needed.\n- **Protection**: controls access based on permissions.\n- **Remote**: acts as local stub for remote object (like RMI).\n\n**How to structure your spoken answer :**\nDefine Proxy. List its types. Give examples: Hibernate lazy loading (virtual), Spring AOP (dynamic proxy). Mention that it's similar to Decorator but for control.\n\n**Follow-up angle to anticipate :**\nBe ready to discuss the difference between Proxy and Decorator."],
  ["Advanced Java", "What is the Observer pattern and how is it used in Java?", "observer-pattern", "Explain Observer.", "**Direct answer :**\nObserver pattern defines a one-to-many dependency between objects, so that when one object changes state, all its dependents are notified. In Java, it's used with \`Observable\`/\`Observer\` (deprecated) or event listeners.\n\n**Why this is asked :**\nInterviewers ask this to test your understanding of event-driven design.\n\n**Breaking it down :**\n- Subject maintains a list of observers and notifies them.\n- Observers implement an update method.\n- Alternative: \`PropertyChangeListener\` or custom events.\n- Used in GUI, messaging, reactive programming.\n\n**How to structure your spoken answer :**\nDefine Observer. Explain the roles. Give an example: a weather station notifying displays. Mention that modern Java uses \`PropertyChangeSupport\` or \`Flow\` API.\n\n**Follow-up angle to anticipate :**\nBe ready to discuss the differences between Observer and Publish-Subscribe."],
  ["Advanced Java", "What is the Strategy pattern?", "strategy-pattern", "Explain Strategy.", "**Direct answer :**\nStrategy pattern defines a family of algorithms, encapsulates each one, and makes them interchangeable. It allows the algorithm to vary independently from clients that use it.\n\n**Why this is asked :**\nInterviewers ask this to test your understanding of behavioral patterns.\n\n**Breaking it down :**\n- Define an interface for the algorithm.\n- Concrete classes implement the algorithm.\n- The context class holds a reference to the strategy and delegates.\n- Example: payment methods (credit card, PayPal).\n\n**How to structure your spoken answer :**\nDefine Strategy. Explain the structure. Give an example. Mention that it promotes Open/Closed principle.\n\n**Follow-up angle to anticipate :**\nBe ready to discuss the difference between Strategy and State pattern."],
  ["Advanced Java", "What is the Template Method pattern?", "template-method", "Explain Template Method.", "**Direct answer :**\nTemplate Method pattern defines the skeleton of an algorithm in a method, deferring some steps to subclasses. It allows subclasses to redefine certain steps without changing the algorithm's structure.\n\n**Why this is asked :**\nInterviewers ask this to test your knowledge of algorithm reusability.\n\n**Breaking it down :**\n- The template method is defined in an abstract class and calls abstract or hook methods.\n- Subclasses implement the abstract methods.\n- Used in frameworks like \`AbstractList\` or \`HttpServlet\`.\n\n**How to structure your spoken answer :**\nDefine Template Method. Explain its purpose. Give an example: \`AbstractList\`'s \`sort\` method using \`Comparable\`. Mention that it's a form of IoC.\n\n**Follow-up angle to anticipate :**\nBe ready to discuss the difference between Template Method and Strategy."],
  ["Advanced Java", "What is the difference between `Factory` and `Abstract Factory` patterns?", "factory-vs-abstractfactory", "Compare Factory and Abstract Factory.", "**Direct answer :**\nFactory Method creates a single product via inheritance. Abstract Factory creates families of related products via composition. Abstract Factory is a factory of factories.\n\n**Why this is asked :**\nInterviewers ask this to test your ability to choose the right pattern.\n\n**Breaking it down :**\n- **Factory Method**: relies on subclasses to decide which concrete product to create. One method to create one product.\n- **Abstract Factory**: provides an interface for creating multiple types of related products. Often implemented using Factory Method itself.\n\n**How to structure your spoken answer :**\nDefine both. Contrast based on complexity and product families. Give examples: Factory for creating a button; Abstract Factory for creating GUI components (buttons, checkboxes) for different OS.\n\n**Follow-up angle to anticipate :**\nBe ready to discuss when to use each."],
  ["Advanced Java", "What is the `Command` pattern?", "command-pattern", "Explain Command.", "**Direct answer :**\nCommand pattern encapsulates a request as an object, allowing parameterization, queuing, logging, and undo operations. It decouples the sender from the receiver.\n\n**Why this is asked :**\nInterviewers ask this to test your knowledge of request-oriented design.\n\n**Breaking it down :**\n- Command interface with \`execute()\` method.\n- Concrete commands implement \`execute()\` and call receiver methods.\n- Invoker stores command and triggers it.\n- Used in transactional operations, menu items, and undo/redo.\n\n**How to structure your spoken answer :**\nDefine Command. Explain its components. Give an example: a remote control with command objects for each button.\n\n**Follow-up angle to anticipate :**\nBe ready to discuss the difference between Command and Strategy."],
  ["Advanced Java", "What is the difference between `State` and `Strategy` patterns?", "state-vs-strategy", "Compare State and Strategy.", "**Direct answer :**\nState pattern changes the behavior of an object when its internal state changes; Strategy pattern selects an algorithm at runtime. In State, the context delegates to state objects; in Strategy, the context uses a strategy object.\n\n**Why this is asked :**\nInterviewers ask this to test your understanding of similar patterns.\n\n**Breaking it down :**\n- **State**: Behavior changes based on state; the state object can transition to other states.\n- **Strategy**: Behavior is chosen once; the strategy object does not know about the context.\n- State is like a dynamic strategy that can change.\n\n**How to structure your spoken answer :**\nDefine both. Contrast based on purpose (state vs algorithm), and how they interact with context. Give examples: State for a VendingMachine, Strategy for sorting algorithms.\n\n**Follow-up angle to anticipate :**\nBe ready to discuss when to use each."],
  ["Advanced Java", "What is the `MVC` pattern and how is it implemented in Spring?", "mvc-pattern", "Explain MVC.", "**Direct answer :**\nMVC (Model-View-Controller) separates application into Model (data/business logic), View (presentation), and Controller (handles input). In Spring MVC, the Controller handles requests, Model is the data (often a Map), and View resolves to JSP, Thymeleaf, etc.\n\n**Why this is asked :**\nInterviewers ask this to test your understanding of web architecture.\n\n**Breaking it down :**\n- **Model**: holds data (Java objects).\n- **View**: renders data (JSP, Thymeleaf).\n- **Controller**: receives requests, calls services, prepares model, and returns view name.\n- Spring uses \`DispatcherServlet\` as front controller.\n\n**How to structure your spoken answer :**\nDefine MVC. Explain the roles. Describe Spring MVC's implementation. Give an example of a controller method returning a ModelAndView.\n\n**Follow-up angle to anticipate :**\nBe ready to discuss the difference between Spring MVC and other MVC frameworks."],
  ["Advanced Java", "What is the `Dependency Injection` pattern and how is it implemented in Spring?", "di-pattern", "Explain DI pattern.", "**Direct answer :**\nDependency Injection (DI) is a pattern where objects receive their dependencies from an external source rather than creating them internally. In Spring, DI is implemented via the IoC container using constructor, setter, or field injection.\n\n**Why this is asked :**\nInterviewers ask this to test your understanding of the core of Spring.\n\n**Breaking it down :**\n- As earlier, DI decouples classes and makes them testable.\n- Spring uses \`@Autowired\`, \`@Inject\`, or XML to inject dependencies.\n- The container manages lifecycle and wiring.\n\n**How to structure your spoken answer :**\nDefine DI. Explain its benefits. Mention Spring's implementation. Give an example of constructor injection with \`@Autowired\`.\n\n**Follow-up angle to anticipate :**\nBe ready to discuss the difference between DI and Service Locator."],

  // ==================== JAVA 8+ FEATURES (15) ====================
  ["Advanced Java", "What are the new features in Java 8?", "java8-features", "List Java 8 features.", "**Direct answer :**\nJava 8 introduced Lambda expressions, Stream API, Optional, new Date/Time API, default methods in interfaces, method references, and Nashorn JavaScript engine.\n\n**Why this is asked :**\nInterviewers ask this to check your knowledge of modern Java features.\n\n**Breaking it down :**\n- **Lambda**: functional programming support.\n- **Stream API**: functional operations on collections.\n- **Optional**: avoid null pointers.\n- **Date/Time**: \`LocalDate\`, \`LocalTime\`, etc.\n- **Default methods**: ability to add methods to interfaces without breaking implementations.\n\n**How to structure your spoken answer :**\nList the major features. Explain each briefly. Mention that Java 8 was a major milestone.\n\n**Follow-up angle to anticipate :**\nBe ready to dive into each feature."],
  ["Advanced Java", "What is a Lambda expression and how is it used?", "lambda", "Explain Lambda.", "**Direct answer :**\nLambda expressions provide a concise way to implement functional interfaces (single abstract method) using \`(parameters) -> expression\` syntax. They are used with Streams, functional interfaces like \`Predicate\`, \`Function\`, \`Consumer\`.\n\n**Why this is asked :**\nInterviewers ask this to test your understanding of functional programming in Java.\n\n**Breaking it down :**\n- Syntax: \`(param1, param2) -> { body; }\` or \`param -> expression\`.\n- Can be used to implement \`Runnable\`, \`Comparator\`, etc.\n- They are not syntactic sugar for anonymous classes; they are invokedynamic.\n\n**How to structure your spoken answer :**\nDefine Lambda. Explain syntax. Give examples: \`list.stream().filter(s -> s.startsWith(\"A\"))\`. Mention functional interfaces.\n\n**Follow-up angle to anticipate :**\nBe ready to discuss functional interfaces and method references."],
  ["Advanced Java", "What is a functional interface?", "functional-interface", "Explain functional interface.", "**Direct answer :**\nA functional interface is an interface with exactly one abstract method. It can have default and static methods. It's used as the target type for lambda expressions. Examples: \`Runnable\`, \`Callable\`, \`Predicate\`, \`Function\`.\n\n**Why this is asked :**\nInterviewers ask this to test your understanding of lambda foundations.\n\n**Breaking it down :**\n- Annotated with \`@FunctionalInterface\` (optional).\n- The compiler checks that it has only one abstract method.\n- Many in \`java.util.function\` package.\n\n**How to structure your spoken answer :**\nDefine functional interface. Explain its relation to lambdas. Give examples. Mention the \`@FunctionalInterface\` annotation.\n\n**Follow-up angle to anticipate :**\nBe ready to discuss common functional interfaces like \`Predicate\`, \`Consumer\`, \`Supplier\`, \`Function\`."],
  ["Advanced Java", "What is the Stream API and its benefits?", "stream-api", "Explain Stream API.", "**Direct answer :**\nStream API provides a way to process sequences of elements (from collections, arrays, I/O) using functional-style operations (map, filter, reduce). It supports parallel processing and lazy evaluation.\n\n**Why this is asked :**\nInterviewers ask this to test your ability to write clean and efficient data processing code.\n\n**Breaking it down :**\n- **Intermediate operations**: filter, map, sorted, distinct (lazy).\n- **Terminal operations**: forEach, collect, reduce, count (eager).\n- **Parallel streams**: \`parallelStream()\` for parallelism.\n- Benefits: declarative, readable, and can leverage multi-core.\n\n**How to structure your spoken answer :**\nDefine Stream. Explain the pipeline. Give examples: filtering and mapping a list. Mention that streams are not data structures; they are operations.\n\n**Follow-up angle to anticipate :**\nBe ready to discuss the difference between \`map\` and \`flatMap\`, and how to collect results."],
  ["Advanced Java", "What is the difference between `map` and `flatMap` in Streams?", "map-vs-flatmap", "Compare map and flatMap.", "**Direct answer :**\n\`map\` applies a function to each element and returns a stream of results (one-to-one). \`flatMap\` applies a function that returns a stream for each element, then flattens these streams into a single stream (one-to-many).\n\n**Why this is asked :**\nInterviewers ask this to test your understanding of stream transformations.\n\n**Breaking it down :**\n- \`map\`: \`Stream<R> map(Function<T,R>)\`.\n- \`flatMap\`: \`Stream<R> flatMap(Function<T, Stream<R>>)\`.\n- Use \`flatMap\` to flatten nested collections or to handle optional values.\n\n**How to structure your spoken answer :**\nDefine both. Give examples: \`map\` for extracting a property, \`flatMap\` for merging lists of lists. Emphasize the return type.\n\n**Follow-up angle to anticipate :**\nBe ready to discuss \`flatMap\` with \`Optional\`."],
  ["Advanced Java", "What is `Optional` and why is it used?", "optional", "Explain Optional.", "**Direct answer :**\n\`Optional\` is a container that may or may not contain a non-null value. It is used to avoid \`NullPointerException\` and to explicitly handle the absence of a value. It provides methods like \`isPresent()\`, \`ifPresent()\`, \`orElse()\`, and \`map()\`.\n\n**Why this is asked :**\nInterviewers ask this to test your understanding of null-safety.\n\n**Breaking it down :**\n- It forces handling of absent values.\n- It can be used as return type for methods that may not return a value.\n- It should not be used as a field or method parameter (it's not serializable).\n- Provides functional operations: \`orElseGet()\`, \`orElseThrow()\`.\n\n**How to structure your spoken answer :**\nDefine Optional. Explain its purpose. Give examples: \`Optional.ofNullable(user).map(User::getName).orElse(\"Unknown\")\`. Mention that it's not a silver bullet but encourages null-checking.\n\n**Follow-up angle to anticipate :**\nBe ready to discuss the difference between \`orElse\` and \`orElseGet\`."],
  ["Advanced Java", "What is the new Date/Time API in Java 8?", "java8-datetime", "Explain Date/Time API.", "**Direct answer :**\nThe new Date/Time API (java.time) provides immutable, thread-safe classes for date and time: \`LocalDate\`, \`LocalTime\`, \`LocalDateTime\`, \`ZonedDateTime\`, \`Instant\`, \`Duration\`, \`Period\`, and \`DateTimeFormatter\`. It replaces the problematic \`Date\` and \`Calendar\`.\n\n**Why this is asked :**\nInterviewers ask this to test your knowledge of modern date/time handling.\n\n**Breaking it down :**\n- **LocalDate**: date without time.\n- **LocalTime**: time without date.\n- **LocalDateTime**: both.\n- **ZonedDateTime**: with timezone.\n- **Instant**: timestamp.\n- Operations: \`plusDays()\`, \`minusHours()\`, \`withMonth()\`.\n- Formatting with \`DateTimeFormatter\`.\n\n**How to structure your spoken answer :**\nDefine the API. List key classes. Give examples of creating and manipulating dates. Mention that it's based on ISO-8601.\n\n**Follow-up angle to anticipate :**\nBe ready to discuss the differences between \`java.util.Date\` and \`java.time\`."],
  ["Advanced Java", "What is the difference between `LocalDateTime` and `ZonedDateTime`?", "localdatetime-vs-zoneddatetime", "Compare LocalDateTime and ZonedDateTime.", "**Direct answer :**\n\`LocalDateTime\` represents date-time without timezone. \`ZonedDateTime\` represents date-time with a timezone and handles daylight saving transitions. Use \`ZonedDateTime\` when timezone is important.\n\n**Why this is asked :**\nInterviewers ask this to test your understanding of time zones in applications.\n\n**Breaking it down :**\n- \`LocalDateTime\`: not tied to a timezone; useful for local calculations.\n- \`ZonedDateTime\`: includes zone offset and rules.\n- Use \`ZonedDateTime\` for storage in databases or APIs where timezone matters.\n\n**How to structure your spoken answer :**\nDefine both. Explain when to use each. Give an example: scheduling a meeting across time zones.\n\n**Follow-up angle to anticipate :**\nBe ready to discuss \`Instant\` and conversions between them."],
  ["Advanced Java", "What are default methods in interfaces?", "default-methods", "Explain default methods.", "**Direct answer :**\nDefault methods are methods defined in interfaces with the \`default\` keyword. They provide a default implementation, allowing interfaces to be evolved without breaking implementing classes. Used in the Collection API (e.g., \`forEach\`, \`stream\`).\n\n**Why this is asked :**\nInterviewers ask this to test your knowledge of interface evolution.\n\n**Breaking it down :**\n- They enable multiple inheritance of behavior.\n- They can be overridden by implementing classes.\n- They can call other interface methods.\n- They are useful for adding new methods to interfaces without forcing all implementations to implement them.\n\n**How to structure your spoken answer :**\nDefine default methods. Explain their purpose. Give an example: \`List\` has \`sort()\` default method. Mention that they are a key feature in Java 8 for API evolution.\n\n**Follow-up angle to anticipate :**\nBe ready to discuss the diamond problem and how it's resolved."],
  ["Advanced Java", "What is a `Method Reference`?", "method-reference", "Explain Method Reference.", "**Direct answer :**\nMethod references provide a shorthand for lambda expressions that simply call an existing method. They use the syntax \`ClassName::methodName\` or \`instance::methodName\`. They are of four types: static, instance, constructor, and arbitrary object.\n\n**Why this is asked :**\nInterviewers ask this to test your ability to write concise lambda code.\n\n**Breaking it down :**\n- \`ClassName::staticMethod\`\n- \`object::instanceMethod\`\n- \`ClassName::instanceMethod\` (for a specific object? Actually for arbitrary object of a class: \`String::length\`)\n- \`ClassName::new\` (constructor)\n\n**How to structure your spoken answer :**\nDefine method reference. Explain the types. Give examples: \`list.stream().map(String::toUpperCase)\`. Mention that it's more readable than lambdas.\n\n**Follow-up angle to anticipate :**\nBe ready to discuss when to use method references vs lambdas."],
  ["Advanced Java", "What are the new features in Java 9, 10, 11, 17, etc.?", "java9-17-features", "List features in newer versions.", "**Direct answer :**\nJava 9 introduced modules (JPMS), \`Optional.orElseThrow()\`, \`List.of()\`. Java 10 introduced \`var\` (local-variable type inference). Java 11 added HTTP Client, \`String\` methods (\`isBlank\`, \`lines\`). Java 17 (LTS) added sealed classes, pattern matching for \`instanceof\`, records, and text blocks.\n\n**Why this is asked :**\nInterviewers ask this to gauge your knowledge of recent Java evolution.\n\n**Breaking it down :**\n- **Java 9**: Module system (JPMS), factory methods for collections.\n- **Java 10**: \`var\` for local variables.\n- **Java 11**: HTTP Client (reactive), launch single-file source-code programs.\n- **Java 14**: Records, pattern matching for instanceof.\n- **Java 17**: Sealed classes, enhanced pseudo-random generators.\n\n**How to structure your spoken answer :**\nList features per version, focusing on the most impactful ones. Mention that Java 11 and 17 are LTS.\n\n**Follow-up angle to anticipate :**\nBe ready to dive into records, sealed classes, and var."],
  ["Advanced Java", "What is the `var` keyword in Java 10?", "var-keyword", "Explain var.", "**Direct answer :**\n\`var\` is used for local variable type inference, allowing the compiler to infer the type from the initializer. It improves readability by reducing boilerplate. It cannot be used for fields, method parameters, or without initializer.\n\n**Why this is asked :**\nInterviewers ask this to test your knowledge of modern Java syntax.\n\n**Breaking it down :**\n- \`var\` is a reserved type name, not a keyword.\n- It infers the type at compile time.\n- Example: \`var list = new ArrayList<String>();\` – compiler knows it's \`ArrayList<String>\`.\n- It's especially useful with complex generic types.\n\n**How to structure your spoken answer :**\nDefine var. Explain its benefits and limitations. Give examples. Mention that it does not imply dynamic typing.\n\n**Follow-up angle to anticipate :**\nBe ready to discuss where \`var\` cannot be used (e.g., lambda parameters)."],
  ["Advanced Java", "What are `Records` in Java 14/17?", "records", "Explain Records.", "**Direct answer :**\nRecords are a type of class that act as data carriers, providing transparent data (immutable) with automatically generated constructor, accessors, equals, hashCode, and toString. They are declared using \`record\` keyword.\n\n**Why this is asked :**\nInterviewers ask this to test your knowledge of modern data classes.\n\n**Breaking it down :**\n- Example: \`record Point(int x, int y) {}\`.\n- They are intended for data transfer objects.\n- They are immutable by default.\n- Can have custom constructors and methods.\n\n**How to structure your spoken answer :**\nDefine Records. Explain their purpose: reduce boilerplate. Give an example. Mention that they are final and cannot be extended.\n\n**Follow-up angle to anticipate :**\nBe ready to discuss the differences between Record and plain class."],
  ["Advanced Java", "What are `Sealed Classes` in Java 17?", "sealed-classes", "Explain Sealed Classes.", "**Direct answer :**\nSealed classes restrict which other classes or interfaces may extend or implement them. They are declared with \`sealed\` and \`permits\` keywords. They provide more control over inheritance hierarchies.\n\n**Why this is asked :**\nInterviewers ask this to test your knowledge of advanced OOP.\n\n**Breaking it down :**\n- Example: \`sealed class Shape permits Circle, Rectangle { ... }\`.\n- Only permitted subclasses can extend.\n- They are useful for domain modeling (e.g., algebraic data types).\n\n**How to structure your spoken answer :**\nDefine sealed classes. Explain their purpose: controlling inheritance. Give an example. Mention that they work with pattern matching.\n\n**Follow-up angle to anticipate :**\nBe ready to discuss pattern matching with sealed classes."],
  ["Advanced Java", "What is the `Text Blocks` feature in Java 13/15?", "text-blocks", "Explain Text Blocks.", "**Direct answer :**\nText blocks are multi-line string literals using triple quotes (\`\"\"\"\`). They preserve indentation and newlines, making SQL, JSON, and HTML strings more readable.\n\n**Why this is asked :**\nInterviewers ask this to test your knowledge of modern string handling.\n\n**Breaking it down :**\n- Example: \`String sql = \"\"\" SELECT * FROM users WHERE id = ?; \"\"\";\`.\n- It automatically removes common indentation.\n- It supports escape sequences.\n\n**How to structure your spoken answer :**\nDefine text blocks. Explain their benefits. Give examples for SQL and JSON. Mention that they are available since Java 15 (standard).\n\n**Follow-up angle to anticipate :**\nBe ready to discuss how to concatenate and use placeholders."],

  // ==================== TESTING (5) ====================
  ["Advanced Java", "What is JUnit and how do you write a unit test?", "junit", "Explain JUnit.", "**Direct answer :**\nJUnit is a testing framework for Java. Tests are written using annotations: \`@Test\`, \`@BeforeEach\`, \`@AfterEach\`, \`@ParameterizedTest\`. Assertions like \`assertEquals\`, \`assertTrue\` are used.\n\n**Why this is asked :**\nInterviewers ask this to test your practical testing skills.\n\n**Breaking it down :**\n- JUnit 5 (Jupiter) is the latest.\n- \`@Test\` marks a test method.\n- \`@BeforeEach\` / \`@AfterEach\` for setup/teardown.\n- \`@DisplayName\` for readable names.\n- \`Assertions\` class.\n- \`@ParameterizedTest\` with \`@ValueSource\` for multiple inputs.\n\n**How to structure your spoken answer :**\nDefine JUnit. Describe the basic test structure. Give an example of a simple test. Mention assertions and annotations.\n\n**Follow-up angle to anticipate :**\nBe ready to discuss mocking with Mockito."],
  ["Advanced Java", "What is Mockito and why is it used?", "mockito", "Explain Mockito.", "**Direct answer :**\nMockito is a mocking framework for Java that allows creating mock objects to isolate the unit under test. It is used to stub dependencies and verify interactions.\n\n**Why this is asked :**\nInterviewers ask this to test your knowledge of isolation testing.\n\n**Breaking it down :**\n- Use \`@Mock\` and \`@InjectMocks\`.\n- Use \`when().thenReturn()\` for stubbing.\n- Use \`verify()\` to check method calls.\n- It helps test classes without relying on real dependencies.\n\n**How to structure your spoken answer :**\nDefine Mockito. Explain its purpose: isolate unit tests. Give an example: mocking a repository and testing a service.\n\n**Follow-up angle to anticipate :**\nBe ready to discuss the difference between \`mock\` and \`spy\`."],
  ["Advanced Java", "What is the difference between `mock` and `spy` in Mockito?", "mock-vs-spy", "Compare mock and spy.", "**Direct answer :**\nA \`mock\` creates a completely fake object with no real implementation. A \`spy\` wraps a real object, allowing you to stub some methods while calling real ones for others.\n\n**Why this is asked :**\nInterviewers ask this to test your advanced mocking knowledge.\n\n**Breaking it down :**\n- \`mock\`: all methods return default values unless stubbed.\n- \`spy\`: real methods are called unless stubbed. Use when you need to partially mock.\n\n**How to structure your spoken answer :**\nDefine both. Contrast use cases. Give an example of using \`spy\` to test a method that calls other methods.\n\n**Follow-up angle to anticipate :**\nBe ready to discuss the \`@Spy\` annotation."],
  ["Advanced Java", "What is the `@SpringBootTest` annotation?", "springboottest", "Explain @SpringBootTest.", "**Direct answer :**\n\`@SpringBootTest\` is an annotation for integration testing in Spring Boot. It loads the full application context and allows testing the application as a whole. It can be used with \`@Test\` and \`@AutoConfigureMockMvc\` for web layer testing.\n\n**Why this is asked :**\nInterviewers ask this to test your knowledge of integration testing.\n\n**Breaking it down :**\n- It loads the entire context.\n- Can be configured with \`webEnvironment\` (MOCK, RANDOM_PORT, DEFINED_PORT).\n- Used with \`@MockBean\` to replace beans with mocks.\n- Slower than unit tests, but tests integration.\n\n**How to structure your spoken answer :**\nDefine \`@SpringBootTest\`. Explain its purpose. Mention that it's used for integration tests. Give an example of testing a REST endpoint with \`TestRestTemplate\`.\n\n**Follow-up angle to anticipate :**\nBe ready to discuss \`@WebMvcTest\` for controller slices."],
  ["Advanced Java", "What is the difference between `@MockBean` and `@Mock`?", "mockbean-vs-mock", "Compare @MockBean and @Mock.", "**Direct answer :**\n\`@Mock\` is a Mockito annotation for creating mocks in unit tests (not Spring-aware). \`@MockBean\` is a Spring Boot annotation that creates a mock and replaces any existing bean of the same type in the application context, used in Spring integration tests.\n\n**Why this is asked :**\nInterviewers ask this to test your understanding of Spring testing.\n\n**Breaking it down :**\n- \`@Mock\`: used in pure unit tests with \`MockitoJUnitRunner\` or \`MockitoExtension\`.\n- \`@MockBean\`: used in \`@SpringBootTest\` to mock a dependency for the entire context.\n\n**How to structure your spoken answer :**\nDefine both. Explain the context: \`@Mock\` for unit, \`@MockBean\` for integration. Give examples.\n\n**Follow-up angle to anticipate :**\nBe ready to discuss \`@SpyBean\` and \`@MockitoBean\` (Spring Boot 3.4+)."],

  // ==================== BUILD & DEPLOYMENT (5) ====================
  ["Advanced Java", "What is Maven and what is its lifecycle?", "maven-lifecycle", "Explain Maven and its lifecycle.", "**Direct answer :**\nMaven is a build automation tool for Java projects. Its build lifecycle consists of phases: \`clean\`, \`validate\`, \`compile\`, \`test\`, \`package\`, \`verify\`, \`install\`, \`deploy\`. Plugins execute goals during these phases.\n\n**Why this is asked :**\nInterviewers ask this to test your knowledge of build tools.\n\n**Breaking it down :**\n- Maven uses a POM (Project Object Model) file.\n- The default lifecycle: \`compile\` -> \`test\` -> \`package\` -> \`install\` -> \`deploy\`.\n- Plugins like \`maven-compiler-plugin\`, \`maven-surefire-plugin\`.\n- Dependencies are managed from Central repository.\n\n**How to structure your spoken answer :**\nDefine Maven. Explain the lifecycle phases. Mention that you can run \`mvn clean install\`. Give examples of common plugins.\n\n**Follow-up angle to anticipate :**\nBe ready to discuss the differences between Maven and Gradle."],
  ["Advanced Java", "What is Gradle and how does it differ from Maven?", "gradle-vs-maven", "Compare Gradle and Maven.", "**Direct answer :**\nGradle is a build tool that uses a Groovy/Kotlin DSL for flexibility. It is more performant due to incremental builds and caching. Maven is convention-based and uses XML; Gradle is more flexible and powerful.\n\n**Why this is asked :**\nInterviewers ask this to test your knowledge of build tools.\n\n**Breaking it down :**\n- **Maven**: XML, convention over configuration, dependency management, standard lifecycle.\n- **Gradle**: Groovy/Kotlin DSL, incremental builds, multi-project builds, better performance.\n\n**How to structure your spoken answer :**\nDefine both. Contrast syntax, flexibility, performance. Mention that Gradle is gaining popularity.\n\n**Follow-up angle to anticipate :**\nBe ready to discuss how to convert a Maven project to Gradle."],
  ["Advanced Java", "What is a `JAR` and `WAR` file?", "jar-vs-war", "Explain JAR and WAR.", "**Direct answer :**\nJAR (Java Archive) is a package for Java libraries and applications; it contains .class files, resources, and a manifest. WAR (Web Archive) is for web applications; it contains servlets, JSPs, and web.xml.\n\n**Why this is asked :**\nInterviewers ask this to test your knowledge of packaging.\n\n**Breaking it down :**\n- **JAR**: can be executed with \`java -jar\` if it has a main class. Used for libraries or standalone apps.\n- **WAR**: deployed to a web container (Tomcat). Contains \`WEB-INF/\` with classes, libraries, and deployment descriptor.\n- Spring Boot can create executable JARs with embedded server.\n\n**How to structure your spoken answer :**\nDefine both. Explain contents and use. Mention the difference in deployment.\n\n**Follow-up angle to anticipate :**\nBe ready to discuss the \`EAR\` file."],
  ["Advanced Java", "What is the purpose of the `pom.xml` file in Maven?", "pom-xml", "Explain pom.xml.", "**Direct answer :**\n\`pom.xml\` is the Project Object Model file for Maven. It defines project metadata, dependencies, build plugins, and configuration. It is the core of a Maven project.\n\n**Why this is asked :**\nInterviewers ask this to test your understanding of Maven configuration.\n\n**Breaking it down :**\n- Coordinates: groupId, artifactId, version.\n- Dependencies: includes scope, exclusions.\n- Build: plugins, resources, final name.\n- Properties: version management.\n\n**How to structure your spoken answer :**\nDefine pom.xml. Explain its key sections. Give an example of a simple pom. Mention that it's inherited from parent.\n\n**Follow-up angle to anticipate :**\nBe ready to discuss dependency management and scopes."],
  ["Advanced Java", "What is a container in Java EE and what are its responsibilities?", "javaee-container", "Explain Java EE container.", "**Direct answer :**\nA Java EE container provides the runtime environment for Java EE components. It manages lifecycle, dependency injection, security, transactions, and concurrency. Examples: Web container (for servlets/JSP), EJB container (for enterprise beans).\n\n**Why this is asked :**\nInterviewers ask this to test your understanding of Java EE architecture.\n\n**Breaking it down :**\n- **Web container**: manages servlets, JSPs, filters.\n- **EJB container**: manages EJB components, transactions, security.\n- **Application client container**: manages standalone clients.\n- Responsibilities: component lifecycle, resource pooling, transaction management, security, and concurrency.\n\n**How to structure your spoken answer :**\nDefine the container. List types. Explain responsibilities. Mention application servers (WildFly, WebLogic).\n\n**Follow-up angle to anticipate :**\nBe ready to discuss the difference between Java EE container and Spring container."],
];

const prisma = new PrismaClient();

const buildWhyInterviewersAsk = (question: string, shortDescription: string) =>
  `Interviewers ask this to check whether you can explain Java concepts clearly and connect them to practical engineering decisions. ${shortDescription} A strong response should address the purpose, the relevant trade‑offs, and how you would verify the result rather than reciting a definition.`;

const buildCommonMistakes = (question: string) => [
  `Giving a memorized definition without explaining how it applies to: ${question}`,
  "Listing features without explaining the safety, performance, or operational trade‑off.",
  "Ignoring security boundaries, persistence, failure handling, or how the solution would be tested.",
];

async function main() {
  const category = await prisma.category.upsert({
    where: { slug: "advanced-java" },
    update: { name: "Advanced Java", group: "Technology", description: "Advanced Java interview questions." },
    create: { name: "Advanced Java", slug: "advanced-java", group: "Technology", description: "Advanced Java interview questions." },
  });
  const subcategory = await prisma.subcategory.upsert({
    where: { categoryId_slug: { categoryId: category.id, slug: "advanced-java" } },
    update: {},
    create: { name: "Advanced Java", slug: "advanced-java", categoryId: category.id },
  });

  for (let topicIndex = 0; topicIndex < topics.length; topicIndex += 1) {
    const [, question, slug, shortDescription, sampleAnswer] = topics[topicIndex];
    const commonMistakes = buildCommonMistakes(question);
    const followUpQuestions = [
      topics[(topicIndex + 1) % topics.length][1],
      topics[(topicIndex + 2) % topics.length][1],
      topics[(topicIndex + 3) % topics.length][1],
    ];
    await prisma.interviewQuestion.upsert({
      where: { slug },
      update: {
        question,
        categoryId: category.id,
        subcategoryId: subcategory.id,
        experienceLevel: ExperienceLevel.MID_LEVEL,
        difficulty: Difficulty.MEDIUM,
        interviewType: InterviewType.TECHNICAL,
        shortDescription,
        explanation: buildWhyInterviewersAsk(question, shortDescription),
        sampleAnswer,
        detailedAnswer: sampleAnswer,
        keyPoints: [],
        commonMistakes,
        followUpQuestions,
        tags: ["Advanced Java"],
        isPublished: true,
      },
      create: {
        question,
        slug,
        categoryId: category.id,
        subcategoryId: subcategory.id,
        experienceLevel: ExperienceLevel.MID_LEVEL,
        difficulty: Difficulty.MEDIUM,
        interviewType: InterviewType.TECHNICAL,
        shortDescription,
        explanation: buildWhyInterviewersAsk(question, shortDescription),
        sampleAnswer,
        detailedAnswer: sampleAnswer,
        keyPoints: [],
        commonMistakes,
        followUpQuestions,
        tags: ["Advanced Java"],
        isPublished: true,
      },
    });
  }

  console.log(`Imported ${topics.length} Advanced Java questions.`);
}

main()
  .catch((error) => {
    console.error(error);
    process.exitCode = 1;
  })
  .finally(() => prisma.$disconnect());

export const slugify = (value: string) => value.toLowerCase().replace(/[^a-z0-9]+/g, "-").replace(/(^-|-$)/g, "");